void str_num(NPtr<char> out, int n) {
    if (n < 0) n = 0;
    if (n > 999) n = 999;
    int k = 0;
    if (n >= 100) out[k++] = (char)('0' + n / 100);
    if (n >= 10) out[k++] = (char)('0' + (n / 10) % 10);
    out[k++] = (char)('0' + n % 10);
    out[k] = 0;
}

