static NVar<int> n_items(0); /* (private: its N64 place, bound by nm_bind) */

static NPtr<Item> add(int type) {
    if (n_items >= 192) return 0;
    NPtr<Item> it = &items[n_items++];
    it->type = (u8)type; it->scale = 1; it->x = it->y = it->w = it->h = 0; it->img = 0; it->rgba = 0;
    it->text[0] = 0;
    return it;
}

static NVar<int> dbg_no_gtext(0); /* (private: its N64 place, bound by nm_bind) */

void draw_gtext(NPtr<char> s, u32 style, int cx, int y, u32 rgba) {
    if (dbg_no_gtext) return;
    NPtr<Item> it = add(IT_GTEXT);
    if (!it) return;
    it->str = s; it->style = style; it->x = (s16)cx; it->y = (s16)y; it->rgba = rgba;
}

