static void flush_cb(u32 at, u32 w0, u32 w1, NPtr<void> ctx) {
    (void)at;
    if ((w0 >> 24) != 0xFF) return;
    NPtr<FlushScan> fs = (NPtr<FlushScan>)ctx;
    fs->last_cimg = ((w1) & 0x1FFFFFFFu);
    if (!fs->w && ((w1) & 0x1FFFFFFFu) == ((fs->fb) & 0x1FFFFFFFu)) {
        int w = (int)(w0 & 0xFFF) + 1;
        if (w >= 256 && w <= 1024) fs->w = w;
    }
}
void nm_entry(u32 arg0, u32 arg1, u32 arg2, P<u32> arg3) {
    flush_cb((u32)arg0, (u32)arg1, (u32)arg2, NPtr<void>(arg3.a));
}
