static NVar<int> mode_latched(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> mode_running(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> mode_next(lift_mod_address(0, 0x160400));

static NVar<int> mode_sv_seen(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> mode_migrated(0); /* (private: its N64 place, bound by nm_bind) */

static void settings_migrate(void) {
    int sv = (int)plat_config(NPtr<char>(lift_mod_address(0, 0x934FF)), 0);
    mode_sv_seen = sv;
    if (sv < 2) {
        int ext = (int)plat_config(NPtr<char>(lift_mod_address(0, 0x931E5)), 1) != 0;
        plat_config_set(NPtr<char>(lift_mod_address(0, 0x933C2)), 0);
        for (int k = RO_EXT0; (NM_TICK(), ( k < RO_EXT0 + 4)); k++) plat_config_set(roster_opt_key[k], (u32)ext);
        plat_config_set(NPtr<char>(lift_mod_address(0, 0x93AD5)), 0);
    }
    if (sv < 3) { plat_config_set(NPtr<char>(lift_mod_address(0, 0x93D9E)), 0); plat_config_set(NPtr<char>(lift_mod_address(0, 0x91D5B)), 0); }
    if (sv < 4) { plat_config_set(NPtr<char>(lift_mod_address(0, 0x93D9E)), 1); plat_config_set(NPtr<char>(lift_mod_address(0, 0x91D5B)), 1); }
    if (sv >= 1 && sv < 5) {
        int arcade_was_on = (int)plat_config(NPtr<char>(lift_mod_address(0, 0x9443E)), 1) != 0;
        plat_config_set(NPtr<char>(lift_mod_address(0, 0x93EA7)), arcade_was_on ? MODE_ARCADE : MODE_REGULAR);
        mode_migrated = arcade_was_on ? 2 : 1;
    }
    if (sv < 5) plat_config_set(NPtr<char>(lift_mod_address(0, 0x934FF)), 5);
}

int nm_mode(void) {
    if (!mode_latched) {
        settings_migrate();
        int m = (int)plat_config(NPtr<char>(lift_mod_address(0, 0x93EA7)), MODE_REGULAR) == MODE_ARCADE ? MODE_ARCADE : MODE_REGULAR;
        mode_running = m;
        mode_next = m;
        mode_latched = 1;
    }
    return mode_running;
}

