static int title_loaded(void) { return (*(NPtr<u32>)(0x80111158u)) == 0x27BDFFB8u; }

static int in_menus(void) { return title_loaded() && (*(NPtr<s32>)(0x800457A0u)) == 0; }

static int nobody_playing(void) { return !active[0] && !active[1]; }

static NArr<u8> ro_bank_base(lift_mod_address(0, 0x310), 0x6);

static int between_games(void) {
    if (nm_arcade()) return nobody_playing();
    if (!in_menus()) return 0;
    s16 scr = (*(NPtr<s16>)(0x800457A4u));
    return scr == 0 || scr == 2 || scr == 3 || scr == 4;
}

int arcade_roster_opt(int i) {
    if (i >= RO_BRET_B && i < RO_BRET_B + 6) i = ro_bank_base[i - RO_BRET_B];
    if (!roster_opt_loaded) roster_opts_load();
    if (!op_open && between_games()) roster_live[i] = roster_opt[i];
    const u32 need = arcade_ro_needs(i);
    if (need && !arcade_extras_has(need)) return 0;
    return roster_live[i];
}

