static void removal_s(NPtr<char> p0) { lift_call<void>(nm_ctx, ::nm_native_call_modfn_810C7ED0)(p0); }   // (the original calls it: the stand-in)
static void removal_say() { lift_call<void>(nm_ctx, ::nm_native_call_modfn_810C81C0)(); }   // (the original calls it: the stand-in)

static void roster_opts_load(void) {
    nm_mode();
    void removal_s(NPtr<char> s); void removal_say(void);
    for (int k = 0; (NM_TICK(), ( k < 44)); k++) {
        if (k == RO_MEDIA) {
            roster_opt[k] = roster_live[k] = plat_config(roster_opt_key[k], roster_opt_def[k]) != 0;
            continue;
        }
        roster_opt[k] = roster_live[k] = 1;
        if (k >= RO_BRET_B) continue;
        if (plat_config(roster_opt_key[k], roster_opt_def[k]) == 0) {
            removal_s(NPtr<char>(lift_mod_address(0, 0x920E0))); removal_s(roster_opt_key[k]);
            removal_s(NPtr<char>(lift_mod_address(0, 0x91D62))
                      );
            removal_say();
        }
    }
    roster_opt_loaded = 1;
}

