u32 storylist_file(u32 file, u32 dest) {
    if (file == 0x4C57u) {
        if (dest) for (u32 k = 0; (NM_TICK(), ( k < ((u32)2096))); k++) (*(NPtr<u8>)(dest + k)) = label_custom_story[k];
        return ((u32)2096);
    }
    if (file == 0x4C58u) {
        if (dest) for (u32 k = 0; (NM_TICK(), ( k < ((u32)2096))); k++) (*(NPtr<u8>)(dest + k)) = label_versus[k];
        return ((u32)2096);
    }
    if (file >= 0x4E00u && file < 0x4E00u + 32) {
        u32 i = file - 0x4E00u;
        if (dest) for (u32 k = 0; (NM_TICK(), ( k < 2096)); k++) (*(NPtr<u8>)(dest + k)) = story_tex[i][k];
        return 2096;
    }
    if (file >= (0x4E00u + 32) && file < (0x4E00u + 32) + 3u) {
        u32 i = file - (0x4E00u + 32);
        if (dest) for (u32 k = 0; (NM_TICK(), ( k < 2096)); k++) (*(NPtr<u8>)(dest + k)) = np_cap_tex[i][k];
        return 2096;
    }
    if (file == ((0x4E00u + 32) + 3u)) {
        if (dest) for (u32 k = 0; (NM_TICK(), ( k < 2096)); k++) (*(NPtr<u8>)(dest + k)) = lj_label_tex[k];
        return 2096;
    }
    return 0;
}

