void arcade_rules_preset_done(void) {
    if (!rules_preset_on) return;
    if (!((*(NPtr<u32>)(0x800A957Cu)) & 0x200u)) return;
    (*(NPtr<u8>)(0x800AA044u + 2)) = 0;
    (*(NPtr<u8>)(0x800AA044u + 3)) = 1;
    (*(NPtr<u8>)(0x800AA044u + 4)) = 1;
    (*(NPtr<u8>)(0x800AA044u + 6)) = 1;
}

