void arcade_number_setup(void) {
    dbg_number_setups++;
    if (!gm_on || !((*(NPtr<u32>)(0x800A957Cu)) & 0x200u)) return;
    int n = gm_size < 4 ? 4 : gm_size > 40 ? 40 : gm_size;
    (*(NPtr<s8>)(0x80158159u)) = (s8)n;
    gm_page_index = n >> 2;
}

