static NShrunk<int, 0, 1> number_by_one(nullptr);   // (shrunk to one byte by the mod compiler)

static u32 number_row(void) {
    u32 items = (*(NPtr<u32>)(menu_record(9) + 0x14));
    return ((u32)(items) >= 0x80000400u && (u32)(items) < 0xA0000000u) ? items : 0;
}

static NShrunk<int, 0, 1> np_rows_up(nullptr);   // (shrunk to one byte by the mod compiler)

static int label_text_render(NPtr<u8> t, NPtr<char> text);

static u32 np_row(int r) { u32 it = number_row(); return it ? it + (u32)r * 0x88u : 0; }

static NVar<u32> row_update_at(0); /* (private: its N64 place, bound by nm_bind) */

void arcade_row_update(u32 row) {
    row_update_at = 0;
    if (!(number_by_one || np_rows_up) || !in_menus() || (*(NPtr<s16>)(0x800457A4u)) != 9) return;
    int r = -1;
    for (int k = number_by_one ? 0 : 2; (NM_TICK(), ( k < (np_rows_up ? 8 : 1))); k += 2) if (row == np_row(k)) r = k;
    if (r < 0) return;
    (*(NPtr<u16>)(row + 0x4A)) = (u16)((*(NPtr<u16>)(row + 0x4A)) & 0x00FFu);
    row_update_at = row;
}

