static NShrunk<int, 0, 1> number_by_one(nullptr);   // (shrunk to one byte by the mod compiler)

static NSplit<int, 4> np_page_index_was = {};   // (split by the mod compiler into one variable per element)

static u32 number_row(void) {
    u32 items = (*(NPtr<u32>)(menu_record(9) + 0x14));
    return ((u32)(items) >= 0x80000400u && (u32)(items) < 0xA0000000u) ? items : 0;
}

static const s8 np_min[4] = { 2, 4, 2, 0 };
 static const s8 np_max[4] = { 40, 32, 19, 1 };

static NShrunk<int, 0, 1> np_rows_up(nullptr);   // (shrunk to one byte by the mod compiler)

static int label_text_render(NPtr<u8> t, NPtr<char> text);

static u32 np_row(int r) { u32 it = number_row(); return it ? it + (u32)r * 0x88u : 0; }

void arcade_number_confirm_done(void) {
    if (!gm_on) return;
    if (number_by_one) {
        u32 row = number_row();
        if (row) {
            int v = (*(NPtr<s8>)(row + 0x4E));
            if (v >= 2 && v <= 40) gm_size = v;
        }
        (*(NPtr<s16>)(0x800A958Cu)) = (s16)(gm_size < 4 ? 4 : gm_size);
        (*(NPtr<s8>)(0x80158159u)) = (s8)gm_size;
    } else {
        s32 n = (*(NPtr<s16>)(0x800A958Cu));
        if ((n >> 2) != gm_page_index) gm_size = n;
    }
    if (np_rows_up) {
        for (int g = 1; (NM_TICK(), ( g < 4)); g++) {
            u32 w = np_row(2 * g);
            if (!w || (*(NPtr<u8>)(w + 0x4B))) continue;
            int v = (*(NPtr<s8>)(w + 0x4E));
            if (v < np_min[g] || v > np_max[g] || v == np_page_index_was[g]) continue;
            if (g == 1) gm_ring = v; else if (g == 2) gm_interval = v * 5; else gm_start4 = v != 0;
        }
    }
}

