int arcade_picked_lumberjacks(NPtr<u16> ids, NPtr<u8> looks, int from, int n) {
    int k = 0;
    for (int i = from; (NM_TICK(), ( i < 50 && k < n)); i++) {
        u16 id = (*(NPtr<u16>)(0x800A95A0u + (u32)i * 12u));
        if (id == 0 || id >= 0x1000) continue;
        ids[k] = id; looks[k] = (*(NPtr<u8>)(0x800A95A0u + (u32)i * 12u + 2u)); k++;
    }
    return k;
}

