s32 arcade_rr_entrant(s32 slot) {
    u32 flags = (*(NPtr<u32>)(0x80097EC0u));
    u32 w = ((0x8017FEF0u + 8u) + 0x358u * (u32)(slot));
    if (flags & 0x4000u) {
        int over = 0;
        if ((((*(NPtr<u32>)(0x800A9950u)) & 0x100000u) || (flags & 0x400000u)) && ((*(NPtr<u16>)(((0x8017FEF0u + 8u) + 0x358u * (u32)(0)) + 0x8C)) & 1)) over = 1;
        if (!over) {
            if ((*(NPtr<u32>)(0x80097EC0u)) & 0x04000000u) {
                int i = (*(NPtr<u8>)(w + 0xF0)) + 1;
                int end = (*(NPtr<u8>)(w + 0xF1));
                if (!(i < end)) return 0;
                if (i == end - 1) (*(NPtr<u8>)(w + 0xE9)) |= 4;
                (*(NPtr<u8>)(w + 0xF0)) = (u8)i;
                (*(NPtr<u16>)(w + 0xD0)) = (*(NPtr<u16>)(0x800BD4D0u + 2u * (u32)i));
                (*(NPtr<u8>)(w + 0xE0)) = (*(NPtr<u8>)(0x800A9358u + (u32)i));
                (*(NPtr<s32>)((0x8053B920u + 0x18u) + 0x1Cu * (u32)slot)) = i;
                return 1;
            }
            s32 next = (*(NPtr<s32>)(0x80159214u));
            int arcade = rr_live();
            if (next < (*(NPtr<s32>)(0x80159210u)) && (!arcade || (rr_due > 0 && rr_cpu(slot)))) {
                (*(NPtr<u8>)(w + 0xF0)) = (u8)next;
                (*(NPtr<u16>)(w + 0xD0)) = (*(NPtr<u16>)(0x800BD4D0u + 2u * (u32)next));
                (*(NPtr<u8>)(w + 0xE0)) = (*(NPtr<u8>)(0x800A9358u + (u32)next));
                (*(NPtr<s32>)(0x80159214u)) = next + 1;
                (*(NPtr<s16>)(0x8051C0C0u + 2u * (u32)slot)) = (s16)(*(NPtr<u8>)(0x800A98E0u + (u32)next));
                (*(NPtr<s32>)((0x8053B920u + 0x18u) + 0x1Cu * (u32)slot)) = next;
                if (arcade) {
                    rr_due--;
                    (*(NPtr<s32>)(0x8051C2E0u + 4u * (u32)slot)) = -1;
                }
                return 1;
            }
        }
    }
    (*(NPtr<u8>)(w + 0xF0)) = 0;
    (*(NPtr<u16>)(w + 0xD0)) = 0;
    (*(NPtr<u8>)(w + 0xE0)) = 0;
    if (rr_live() && rr_cpu(slot) && (*(NPtr<s32>)(0x8051C2E0u + 4u * (u32)slot)) >= 0) {
        (*(NPtr<u8>)(w + 0xE1)) &= (u8)~0x10u;
        (*(NPtr<u16>)(w + 0x8C)) |= 1u;
        dbg_rr_kept_out++;
    }
    return 0;
}

