static NArr<u8> void_steps(lift_mod_address(0, 0x172ED0), 0x20);

static NVar<u32> dbg_void_drops(0); /* (private: its N64 place, bound by nm_bind) */

static int void_free_state(s32 st) { return st == 1 || st == 2 || st == 3 || st == 0x31 || st == 0x32; }

void ring_void_guard(void) {
    if ((*(NPtr<u16>)(0x801532C0u)) == 0xFFFFu || qa_void_off) return;
    for (int s = 0, n = nm_slots(); (NM_TICK(), ( s < n)); s++) {
        u32 w = ((0x8017FEF0u + 8u) + 0x358u * (u32)(s));
        float x = *(NPtr<float>)(w + 0xF4); float y = *(NPtr<float>)(w + 0xF8); float z = *(NPtr<float>)(w + 0xFC);
        u16 area = (*(NPtr<u16>)(w + 0x7A)) & 0x7FFu;
        int off = !rr_absent(s) && (area == 1 || area == 2) && y > 60.0f &&
                  (x > 300.0f || x < -300.0f || z > 300.0f || z < -300.0f) && void_free_state((*(NPtr<s32>)(w + 0x0C)));
        if (!off) { void_steps[s] = 0; continue; }
        if (++void_steps[s] < 30) continue;
        void_steps[s] = 0;
        *(NPtr<float>)(w + 0xF8) = 0.0f; *(NPtr<float>)(w + 0x11C) = 0.0f;
        for (u32 k = 0x124; (NM_TICK(), ( k <= 0x154)); k += 12) *(NPtr<float>)(w + k + 4) = 0.0f;
        (*(NPtr<u16>)(w + 0x7A)) = 4;
        dbg_void_drops++;
    }
}

