static void rr_walk_cpu(int s, int on) {
    u32 w = ((0x8017FEF0u + 8u) + 0x358u * (u32)(s));
    if (on) { (*(NPtr<u8>)(w + 0xE1)) |= 0x08; if (s < 4) (*(NPtr<u32>)(0x80097EC0u)) |= 1u << s; }
    else { (*(NPtr<u8>)(w + 0xE1)) &= (u8)~0x08; if (s < 4) (*(NPtr<u32>)(0x80097EC0u)) &= ~(1u << s); }
}

static void rr_walk_in_step(void) {
    if (rr_walk_slot < 0) return;
    u32 w = ((0x8017FEF0u + 8u) + 0x358u * (u32)(rr_walk_slot));
    int outside = ((*(NPtr<u16>)(w + 0x7A)) & 4) != 0;
    if (--rr_walk_in <= 0 || ((*(NPtr<u16>)(w + 0x8C)) & 1) || (!outside && (*(NPtr<s32>)(w + 0x0C)) == 1)) {
        rr_walk_cpu(rr_walk_slot, 0);
        (*(NPtr<u32>)(0x800A9950u)) |= rr_walk_rule; rr_walk_rule = 0;
        rr_walk_slot = -1; rr_walk_in = 0;
        return;
    }
    rr_walk_cpu(rr_walk_slot, outside);
}

