static int exh_rows_in(void) {
    u32 items = (*(NPtr<u32>)(menu_record(7) + 0x14));
    if (!((u32)(items) >= 0x80000400u && (u32)(items) < 0xA0000000u)) return 0;
    for (u32 i = 0; (NM_TICK(), ( i < 6)); i++) if ((*(NPtr<u8>)(items + i * 0x88u + 0x4B)) == 0) return 1;
    return 0;
}

