static int champ_rows(void) {
    int n = (*(NPtr<u8>)((0x8014DFC8u + 8u * (u32)(22)) + 4));
    return n > 11 ? 11 : n;
}

static u32 champ_items(void) {
    u32 items = (*(NPtr<u32>)(menu_record(22) + 0x14));
    return (((u32)(items) >= 0x80000400u && (u32)(items) < 0xA0000000u)) ? items : 0;
}

static void list_fade_in(void) {
    u32 items = champ_items();
    if (items) for (int k = 0; (NM_TICK(), ( k < champ_rows())); k++) (*(NPtr<u8>)(items + (u32)k * 0x88u + 0x56)) = 0;
}

