static u16 sel_hover(void) {
    s16 scr = (*(NPtr<s16>)(0x800457A4u));
    u32 rec = menu_record(scr); u32 items = (*(NPtr<u32>)(rec + 0x14));
    s32 cur = (*(NPtr<s16>)(rec + 4));
    if (is_select(scr) && ((u32)(items) >= 0x80000400u && (u32)(items) < 0xA0000000u) && cur >= 0 && cur < 9) {
        u16 id = (*(NPtr<u16>)(items + 0x88u * (u32)cur + 0x62u));
        if (id && id < 0x1000) return id;
    }
    return (*(NPtr<u16>)(0x804DC500u));
}

