namespace nm_810A468C { void nm_entry(); }
void modrep_nat_810A468C(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x58);
    frame.keep(0x54, ctx->r31);
    frame.keep(0x50, ctx->r30);
    frame.keep(0x4C, ctx->r23);
    frame.keep(0x48, ctx->r22);
    frame.keep(0x44, ctx->r21);
    frame.keep(0x40, ctx->r20);
    frame.keep(0x3C, ctx->r19);
    frame.keep(0x38, ctx->r18);
    frame.keep(0x34, ctx->r17);
    frame.keep(0x30, ctx->r16);
    nm_ctx = ctx;
    nm_810A468C::nm_entry();
}
