static NVar<int> step_acc(0); /* (private: its N64 place, bound by nm_bind) */

static NShrunk<int, 0, 1> step_extra(nullptr);   // (shrunk to one byte by the mod compiler)

static NVar<u32> dbg_match_steps(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u32> dbg_match_extra(0); /* (private: its N64 place, bound by nm_bind) */
static void movex_chain_step() { lift_call<void>(nm_ctx, ::nm_native_call_modfn_810E3FA4)(); }   // (the original calls it: the stand-in)
static void match_slots_step() { lift_call<void>(nm_ctx, ::nm_native_call_modfn_81122710)(); }   // (the original calls it: the stand-in)

static NVar<int> ms_live(0); /* (private: its N64 place, bound by nm_bind) */

static int match_on(void) {
    s32 m = (*(NPtr<s32>)(0x800457A0u));
    return (m == -2 || m == -6) && (*(NPtr<s32>)(0x801591FCu)) == 2 && !((*(NPtr<u32>)(0x80162A7Cu)) & 2) &&
           (*(NPtr<u8>)(0x80151ED6u)) == 0 && (*(NPtr<s16>)(0x80151EDCu)) == 0;
}

void arcade_match_step(void) {
    if (match_on()) { extern void movex_chain_step(void); movex_chain_step(); }
    {  extern void match_slots_step(void); if (ms_live) match_slots_step(); }
    if (step_extra) return;
    if (!match_on()) { step_acc = 0; return; }
    dbg_match_steps++;
    if (!arcade_speed) { step_acc = 0; return; }
    step_acc += speed_boost;
    if (step_acc < 100) return;
    step_acc -= 100;
    u16 edges[4][2];
    for (u32 i = 0; (NM_TICK(), ( i < 4)); i++) {
        edges[i][0] = (*(NPtr<u16>)(0x8051C140u + 0xCu * i + 6u)); (*(NPtr<u16>)(0x8051C140u + 0xCu * i + 6u)) = 0;
        edges[i][1] = (*(NPtr<u16>)(0x8051C140u + 0xCu * i + 8u)); (*(NPtr<u16>)(0x8051C140u + 0xCu * i + 8u)) = 0;
    }
    step_extra = 1;
    dbg_match_extra++;
    plat_game_call(GF_MATCH_STEP, 0, 0, 0);
    step_extra = 0;
    for (u32 i = 0; (NM_TICK(), ( i < 4)); i++) {
        (*(NPtr<u16>)(0x8051C140u + 0xCu * i + 6u)) = edges[i][0];
        (*(NPtr<u16>)(0x8051C140u + 0xCu * i + 8u)) = edges[i][1];
    }
}

