static NVar<u32> page_last(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> page_frames(0); /* (private: its N64 place, bound by nm_bind) */

int arcade_story_page(void) {
    if (dbg_passive) return 0;
    if (nm_arcade()) {
        if (goal == G_VERSUS && leave_fast && goal_wait <= 0) return 1;
        if (!short_menus) return 0;
        if (phase != PLAY || game_mode != GM_STORY || cont_player >= 0 || goal != G_NONE) return 0;
    } else if (!short_menus) return 0;
    if (frame_no - page_last > 6) page_frames = 0;
    page_last = frame_no;
    if (++page_frames < 330) return 0;
    page_frames = 0;
    return 1;
}

