static NVar<u32> qa_ps_draws(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u32> qa_ps_alpha(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u32> qa_ps_cmin(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u32> qa_ps_cmax(0); /* (private: its N64 place, bound by nm_bind) */

void arcade_qa_sprite_draw(u32 req, s32 alpha) {
    if (!qa_modes || !((u32)(req) >= 0x80000400u && (u32)(req) < 0xA0000000u) || (*(NPtr<u32>)(req + 8)) != 0x1000000Fu) return;
    qa_ps_draws++;
    if ((u32)alpha > qa_ps_alpha) qa_ps_alpha = (u32)alpha & 0xFFu;
    u32 c = (*(NPtr<u32>)(0x8014A5ACu));
    if (c < qa_ps_cmin) qa_ps_cmin = c;
    if (c > qa_ps_cmax) qa_ps_cmax = c;
}

