static void sprite_hide(u32 id) {
    u32 t = (*(NPtr<u32>)(0x8010581Cu));
    if (!((u32)(t) >= 0x80000400u && (u32)(t) < 0xA0000000u)) return;
    for (int i = 0; (NM_TICK(), ( i < 0x60)); i++) {
        u32 e = t + (u32)i * 12u;
        u32 req = (*(NPtr<u32>)(e));
        if (!((u32)(req) >= 0x80000400u && (u32)(req) < 0xA0000000u)) continue;
        if ((*(NPtr<u32>)(req + 8)) != id) continue;
        (*(NPtr<s16>)(e + 4)) = 0;
        (*(NPtr<u32>)(e + 8)) = 0;
    }
}

