 void qa_hook_demo_flags(void) {
    if (qa_on == 1 && qa_setup_flags) (*(NPtr<u32>)(0x800A957Cu)) = qa_setup_flags;
    if (qa_on == 1 && (qa_setup_flags & 0x80u)) {
        u32 f = (*(NPtr<u32>)(0x80097EC0u)) & 0xFF00000Fu;
        f |= 0x80000u | ((qa_setup_flags & 1u) ? 0x1400u : (qa_setup_flags & 4u) ? 0x8800u : (qa_setup_flags & 8u) ? 0x20840u : 0u);
        (*(NPtr<u32>)(0x80097EC0u)) = f;
    }
}

