s32 modrep_nat_810A5108(recomp_context* ctx, s32 arg0, P<u16> arg1, P<u16> arg2) {
    LiftFrame frame(ctx, 0x38);
    frame.keep_double(0x30, ctx->f22.u64);
    frame.keep_double(0x28, ctx->f20.u64);
    frame.keep(0x24, ctx->r31);
    frame.keep(0x20, ctx->r30);
    frame.keep(0x1C, ctx->r23);
    frame.keep(0x18, ctx->r22);
    frame.keep(0x14, ctx->r21);
    frame.keep(0x10, ctx->r20);
    frame.keep(0xC, ctx->r19);
    frame.keep(0x8, ctx->r18);
    frame.keep(0x4, ctx->r17);
    frame.keep(0x0, ctx->r16);
    nm_ctx = ctx;
    return nm_810A5108::nm_entry(arg0, arg1, arg2);
}
