static int qa_fbad(u32 a) { return ((*(NPtr<u32>)(a)) & 0x7F800000u) == 0x7F800000u; }


static int qa_headgrab_input(NPtr<u16> held, NPtr<u16> pressed) {
    static NVar<int> t(lift_mod_address(0, 0x174444)); /* (private: its N64 place) */ /* qa_headgrab_input.t: the N64 size */ static NVar<int> wait(lift_mod_address(0, 0x12E334)); /* (private: its N64 place) */ /* qa_headgrab_input.wait: the N64 size */
    static NVar<float> px(lift_mod_address(0, 0x174448)); /* (private: its N64 place) */ /* qa_headgrab_input.px: the N64 size */ static NVar<float> py(lift_mod_address(0, 0x17444C)); /* (private: its N64 place) */ /* qa_headgrab_input.py: the N64 size */ static NVar<float> pz(lift_mod_address(0, 0x174450)); /* (private: its N64 place) */ /* qa_headgrab_input.pz: the N64 size */ static NVar<s32> pf(lift_mod_address(0, 0x174454)); /* (private: its N64 place) */ /* qa_headgrab_input.pf: the N64 size */
    u32 me = ((0x8017FEF0u + 8u) + 0x358u * (u32)(0)); u32 v = ((0x8017FEF0u + 8u) + 0x358u * (u32)(1));
    u32 st = (*(NPtr<u32>)(me + 0x14)) & 0xFFFFu; u32 vst = (*(NPtr<u32>)(v + 0x14)) & 0xFFFFu;
    if (t > 0) {
        t--;
        if ((vst != 49 && vst != 50) || (st != 1 && st != 2 && st != 3)) { t = 0; return 0; }
        (*(NPtr<float>)(me + 0xF4)) = px; (*(NPtr<float>)(me + 0xF8)) = py; (*(NPtr<float>)(me + 0xFC)) = pz;
        (*(NPtr<float>)(me + 0x118)) = px; (*(NPtr<float>)(me + 0x11C)) = py; (*(NPtr<float>)(me + 0x120)) = pz;
        for (u32 b = 0x124; (NM_TICK(), ( b <= 0x154)); b += 12) { (*(NPtr<float>)(me + b)) = px; (*(NPtr<float>)(me + b + 4)) = py; (*(NPtr<float>)(me + b + 8)) = pz; }
        (*(NPtr<s32>)(me + 0x104)) = pf;
        u16 bt = qa_headgrab == 2 ? 0x4000 : 0x8000;
        if (t == 2 || t == 1) { *held = bt; if (t == 2) *pressed = bt; }
        return 1;
    }
    if (--wait > 0) return 0;
    if ((vst != 49 && vst != 50) || (st != 1 && st != 2 && st != 3)) return 0;
    if (qa_fbad(v + 0xF4) || qa_fbad(v + 0xF8) || qa_fbad(v + 0xFC)) return 0;
    s32 f = (*(NPtr<s32>)(v + 0x104)) & 4095;
    float a = (float)f * (6.2831853f / 4096.0f); float sn = qa_sin(a); float cs = qa_sin(a + 1.5707963f);
    px = (*(NPtr<float>)(v + 0xF4)) - 110.0f * sn; py = (*(NPtr<float>)(v + 0xF8)); pz = (*(NPtr<float>)(v + 0xFC)) - 110.0f * cs; pf = f;
    t = 24; wait = 150;
    return 0;
}

