int qa_table_input(s32 slot, NPtr<u16> held, NPtr<u16> pressed) {
    static NVar<int> t(lift_mod_address(0, 0x17303C)); /* (private: its N64 place) */ /* qa_table_input.t: the N64 size */ static NVar<int> k(lift_mod_address(0, 0x173040)); /* (private: its N64 place) */ /* qa_table_input.k: the N64 size */
    if (qa_headgrab && slot == 0 && ((*(NPtr<s32>)(0x800457A0u)) == -2 || (*(NPtr<s32>)(0x800457A0u)) == -6) && (*(NPtr<u16>)(0x801532C0u)) != 0xFFFF && (*(NPtr<u16>)(0x801532C0u)) >= 120)
        return qa_headgrab_input(held, pressed);
    if (!qa_table || slot != 0 || ((*(NPtr<s32>)(0x800457A0u)) != -2 && (*(NPtr<s32>)(0x800457A0u)) != -6) || (*(NPtr<u16>)(0x801532C0u)) == 0xFFFF || (*(NPtr<u16>)(0x801532C0u)) < 120) return 0;
    u32 w = ((0x8017FEF0u + 8u) + 0x358u * (u32)(0));
    if (t > 0) {
        t--;
        *held = k & 1 ? 0x0100 : 0x0200;
        if (t == 44) *pressed = 0x0008;
        *held |= 0x0008;
        return 1;
    }
    static NVar<int> wait(lift_mod_address(0, 0x12E2E0)); /* (private: its N64 place) */ /* qa_table_input.wait: the N64 size */
    u32 st = (*(NPtr<u32>)(w + 0x14)) & 0xFFFFu;
    if (--wait > 0 || (st != 1 && st != 2 && st != 3) || qa_fbad(w + 0xF4) || qa_fbad(w + 0xFC)) return 0;
    k++;
    float x = k & 1 ? -190.0f : 190.0f; float z = (k >> 1) & 1 ? -500.0f : -650.0f;
    s32 fc = k & 1 ? 1024 : 3072;
    (*(NPtr<float>)(w + 0xF4)) = x; (*(NPtr<float>)(w + 0xF8)) = 0.0f; (*(NPtr<float>)(w + 0xFC)) = z;
    (*(NPtr<float>)(w + 0x118)) = x; (*(NPtr<float>)(w + 0x11C)) = 0.0f; (*(NPtr<float>)(w + 0x120)) = z;
    for (u32 a = 0x124; (NM_TICK(), ( a <= 0x154)); a += 12) { (*(NPtr<float>)(w + a)) = x; (*(NPtr<float>)(w + a + 4)) = 0.0f; (*(NPtr<float>)(w + a + 8)) = z; }
    (*(NPtr<u16>)(w + 0x7A)) = 4;
    (*(NPtr<s32>)(w + 0x104)) = fc;
    qa_forced++; t = 45; wait = 200;
    return 0;
}

