static void unlock_everything(void) {
    if (!unlock_all) return;
    for (u32 i = 0; (NM_TICK(), ( i < 25u)); i++) (*(NPtr<u8>)(0x800BD910u + i)) = 0xFF;
    if (!in_menus()) return;
    u32 img = (*(NPtr<u32>)(0x80062C20u));
    if (((u32)(img) >= 0x80000400u && (u32)(img) < 0xA0000000u))
        for (u32 i = 0; (NM_TICK(), ( i < 25u)); i++) (*(NPtr<u8>)(img + 0x6B67u + i)) = 0xFF;
}

