static u32 menu_record(int screen) { return 0x80158360u + (u32)screen * 0x138; }
static void menu_change(int p0) { lift_call<void>(nm_ctx, ::nm_native_call_modfn_810B9AFC)(p0); }   // (the original calls it: the stand-in)

static int menu_choose(int screen, int item_index, int action) {
    u32 rec = menu_record(screen);
    u32 items = (*(NPtr<u32>)(rec + 0x14));
    if (!((u32)(items) >= 0x80000400u && (u32)(items) < 0xA0000000u)) {
        if (screen >= 2 && screen <= 4) plat_game_call(GF_PAGE_INIT, (u32)screen, 0, 0);
        items = (*(NPtr<u32>)(rec + 0x14));
        if (!((u32)(items) >= 0x80000400u && (u32)(items) < 0xA0000000u)) return -1;
    }
    u32 item = items + (u32)item_index * 0x88u;
    int next = plat_game_call(GF_ACTION, (u32)action, rec, item);
    (*(NPtr<s16>)(0x8015B7C8u)) = 1;
    if (next >= 0 && next < 0x40) menu_change(next);
    return next;
}

