static void rr_configure(void) {
    u32 rec = menu_record(22);
    u32 items = (*(NPtr<u32>)(rec + 0x14));
    plat_game_call(GF_ACTION, 0x0404, rec, items + 7 * 0x88u);
    plat_game_call(GF_RULES_PRESET, 1, 0, 0);
    (*(NPtr<u32>)(0x800A957Cu)) = 0x00020200u;
    plat_game_call(GF_SETTINGS_SLOT, 2, 0, 0);
    (*(NPtr<u16>)(0x800A957Cu + 4)) = 0x0318;
    (*(NPtr<s16>)(0x800A9582u)) = 4;
    (*(NPtr<s16>)(0x800A958Cu)) = (s16)(rumble_size + 2);
    (*(NPtr<u8>)(0x80784CB0u)) = (u8)(qa_ring() ? qa_ring() : rumble_ring);
    for (u32 r = 0; (NM_TICK(), ( r < 4)); r++) {
        u32 p = 0x800A95A0u + r * 12u;
        (*(NPtr<u16>)(p)) = 0xFFFF; (*(NPtr<u8>)(p + 2)) = 0xFF; (*(NPtr<u8>)(p + 3)) = r == 0;
    }
    int qa_ar = qa_on == 2 && qa_arena >= 1 && qa_arena <= arena_count();
    arena_choose(qa_ar ? qa_arena - 1 : -1);
    (*(NPtr<u8>)(0x800A946Fu)) = qa_ar ? (u8)arena_venue(qa_arena - 1) : (u8)6;
    for (u32 i = 0; (NM_TICK(), ( i < 12)); i++) (*(NPtr<u8>)(0x800AA044u + i)) = rr_rules_rumble[i];
    (*(NPtr<u32>)(0x800A9950u)) = 0x00040C00u;
    (*(NPtr<u32>)(0x80550720u + 0xCu)) = 0xFFFFFFFFu;
    (*(NPtr<u8>)(0x800A3E31u)) = 0xFF; (*(NPtr<u8>)(0x800A9461u)) = 0xFF;
    u8 venue = qa_ar ? (u8)arena_venue(qa_arena - 1) : (u8)6;
    (*(NPtr<u8>)(0x80158154u)) = 0; (*(NPtr<u8>)(0x80158155u)) = 3; (*(NPtr<u8>)(0x80158156u)) = venue; (*(NPtr<u8>)(0x80158157u)) = 1;
    (*(NPtr<u8>)(0x80158158u)) = 0xFF; (*(NPtr<u8>)(0x80158159u)) = (u8)(rumble_size + 2);
    (*(NPtr<u32>)(0x80097EC0u)) = 0x4000u | 0xFu;
    (*(NPtr<u8>)(0x800A10F1u - 1)) = 5; (*(NPtr<u8>)(0x800A10F1u)) = venue;
    (*(NPtr<u8>)(0x800A9578u)) = 7;
}

static void rr_open(int rebuild) {
    rr_configure();
    gm_live = 0; gm_on = 0;
    rr_rebuild = rebuild;
    rr_player_out = 0;
    rr_mode = RR_SELECT;
    (*(NPtr<s16>)(0x8015B7C8u)) = 1;
    if (!rebuild) { menu_change(26); return; }
    u32 p = 0x800A95A0u;
    (*(NPtr<u16>)(p)) = sp_pick; (*(NPtr<u8>)(p + 2)) = sp_costume;
    plat_game_call(GF_SELECT_DONE, 1, 0, 0);
    plat_game_call(GF_FINALIZE, 0, 0, 0);
    menu_change(42);
}

