static void demo_label_off(void) {
    if (!nm_arcade()) return;
    if ((*(NPtr<s32>)(0x800457A0u)) != -6 || !((*(NPtr<u32>)(0x80097EC0u)) & 0x02000000u)) return;
    if ((*(NPtr<u32>)(0x80144B70u)) != 0x038E038Cu || (*(NPtr<u16>)(0x801532C0u)) == 0xFFFF) return;
    u32 quad = (*(NPtr<u32>)(0x801556B8u + 0x10)); u32 list = (*(NPtr<u32>)(0x801556B8u + 0x1C));
    if (!((u32)(quad) >= 0x80000400u && (u32)(quad) < 0xA0000000u) || !((u32)(list) >= 0x80000400u && (u32)(list) < 0xA0000000u)) return;
    if ((*(NPtr<u32>)(list)) == 0xDF000000u) return;
    int found = 0;
    for (int i = 0; (NM_TICK(), ( i < 8)); i++)
        if (((*(NPtr<u32>)(list + 8u * (u32)i)) >> 24) == 0x01 && ((*(NPtr<u32>)(list + 8u * (u32)i + 4)) & 0xFFFFFF) == (quad & 0xFFFFFF)) found = 1;
    if (!found) return;
    (*(NPtr<u32>)(list)) = 0xDF000000u;
    (*(NPtr<u32>)(list + 4)) = 0;
}

