;


static NArr<Say> says(lift_mod_address(0, 0x172FE8), 0x48);

static NVar<int> n_says(0); /* (private: its N64 place, bound by nm_bind) */

static int says_on_title(void) { return title_loaded() && (*(NPtr<s32>)(0x800457A0u)) == 0 && (*(NPtr<s16>)(0x800457A4u)) == 0; }

static void say_text(NPtr<char> s, u32 style, int cx, int y, u32 rgba) {
    if (says_on_title()) {
        if (n_says < 6) {
            int h = ((style & 0x8000u) ? 25 : 15) + ((style & 0x0020u) ? 16 : 0);
            NPtr<Say> t = &says[n_says++];
            t->s = s; t->style = style; t->x = (s16)cx; t->y = (s16)(y + h / 2 - 5);
        }
        return;
    }
    draw_gtext(s, style, cx, y, rgba);
}

