namespace nm_810B7654 { void nm_entry(); }
void modrep_nat_810B7654(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x30);
    frame.keep(0x2C, ctx->r31);
    frame.keep(0x28, ctx->r30);
    frame.keep(0x24, ctx->r23);
    frame.keep(0x20, ctx->r22);
    frame.keep(0x1C, ctx->r21);
    frame.keep(0x18, ctx->r20);
    frame.keep(0x14, ctx->r19);
    frame.keep(0x10, ctx->r18);
    frame.keep(0xC, ctx->r17);
    frame.keep(0x8, ctx->r16);
    nm_ctx = ctx;
    nm_810B7654::nm_entry();
}
