void flight_event(u32 code, u32 a, u32 b) {
    u32 e = 0x807F2000u + 0x80u + (flight_n % 64) * 16u;
    (*(NPtr<u32>)(e)) = frame_no; (*(NPtr<u32>)(e + 4)) = code; (*(NPtr<u32>)(e + 8)) = a; (*(NPtr<u32>)(e + 12)) = b;
    flight_n++;
    (*(NPtr<u32>)(0x807F2000u + 0x7C)) = flight_n;
}

