static void watch_match(void) {
    if (!match_running() || (*(NPtr<u16>)(0x801532C0u)) < 10) { match_armed = 0; return; }
    if (!match_armed) {
        int all_in = 1;
        for (int s = 0; (NM_TICK(), ( s < 4)); s++) if ((*(NPtr<s32>)(0x8051C2E0u + 4u * (u32)s)) >= 0) all_in = 0;
        if (!all_in) return;
        match_armed = 1; match_lost[0] = match_lost[1] = 0;
        if (challenge_on && game_mode == GM_VERSUS && !challenge_old) challenge_played = 1;
        for (int s = 0; (NM_TICK(), ( s < 4)); s++) {
            s32 pad = (*(NPtr<s32>)(0x8054B7A0u + 4u * (u32)s));
            slot_owner[s] = (s8)((pad == 1 || pad == 2) && (*(NPtr<u8>)(0x8051C100u + (u32)s)) != 0 ? port_player[pad - 1] : -1);
        }
        return;
    }
    for (int pl = 0; (NM_TICK(), ( pl < 2)); pl++) {
        if (!active[pl] || match_lost[pl]) continue;
        int owns = 0; int out = 1;
        for (int s = 0; (NM_TICK(), ( s < 4)); s++) {
            if (slot_owner[s] != pl) continue;
            owns = 1;
            if ((*(NPtr<s32>)(0x8051C2E0u + 4u * (u32)s)) < 0) out = 0;
        }
        if (owns && out) {
            match_lost[pl] = 1;
            if (challenge_on) { challenge_decided(pl); return; }
            if (rr_cont_on && game_mode == GM_STORY && sp_kind == SP_RUMBLE && rr_mode == RR_LIVE) {
                rr_player_out = 1;
                flight_event(FL_PLAYER_OUT, (u32)pl, (u32)free_play);
                rumble_capture();
                if (free_play) { rr_continue(90); continue; }
            }
            if (!free_play) lost_pending[pl] = 1;
        }
    }
}

