static NVar<u16> sp_pick(0); /* (private: its N64 place, bound by nm_bind) */

static NShrunk<int, 0, 1> resume_pending(nullptr);   // (shrunk to one byte by the mod compiler)

static NVar<int> pick_wait(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> pick_steps(0); /* (private: its N64 place, bound by nm_bind) */

int roster_staging(void);
static int auto_pick_c(u16 p0, int p1, int p2) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810BC2B0)(p0, p1, p2); }   // (the original calls it: the stand-in)

static int auto_pick(u16 want) { return auto_pick_c(want, -1, -1); }

static void rumble_capture(void);

static NVar<int> resume_list_wait(0); /* (private: its N64 place, bound by nm_bind) */

static void resume_single(void) {
    if (!resume_pending || phase != PLAY || game_mode != GM_STORY || goal != G_NONE || cont_player >= 0) return;
    if (!in_menus() || menus_loading() || inject_frames > 0) return;
    s16 scr = (*(NPtr<s16>)(0x800457A4u));
    if (scr == 22) {
        if (scr_stable < 20) { resume_list_wait = 0; return; }
        if (sp_kind == SP_RUMBLE) { resume_pending = 0; rr_open(1); return; }
        if (sp_kind == SP_SURVIVAL) { survival_open(); return; }
        (*(NPtr<u8>)(menu_record(22) + 5)) = (u8)sp_belt;
        if (++resume_list_wait < 20) return;
        resume_list_wait = -100;
        pick_steps = 0; pick_wait = 30;
        inject_press(0x8000);
        return;
    }
    if (is_select(scr) && (sp_kind == SP_STORY || sp_kind == SP_SURVIVAL)) {
        if (scr_stable < 30) return;
        int r = auto_pick(sp_pick);
        if (r != 0) resume_pending = 0;
    }
}

