static void story_card_skip(s16 scr, s32 step) {
    if (!card_confirmed && scr_stable >= 4 && (*(NPtr<u16>)(0x80097ED6u)) == 7 && story_active()) {
        if (inject_frames == 0 && ++card_tally % 20 == 0) inject_press(0x8000);
    } else if (!card_confirmed && scr_stable >= 4) {
        dbg_card_next = menu_confirm(scr, 0);
        card_confirmed = 1;
        if (step != 44) (*(NPtr<s32>)(0x800A872Cu)) = 41;
        (*(NPtr<s32>)(0x800457A0u)) = -8;
        (*(NPtr<s16>)(0x800457A6u)) = 23;
        (*(NPtr<u32>)(0x800A9444u)) = 0;
        scr_stable = 0;
    }
}

