static s16 hud_t(u32 table, int place) { return (*(NPtr<s16>)(table + 2u * (u32)place)); }

static void rrm_put(int s, int p) {
    u32 rec = 0x8016B9F0u + 0xCu * (u32)s; u32 bone = 0xDCu * (u32)s; u32 part = 0x34u * (u32)s;
    (*(NPtr<u8>)(rec)) = (u8)(((*(NPtr<u8>)(rec)) & 0xC0u) | (u32)p);
    (*(NPtr<s16>)(rec + 8)) = hud_t(0x807847F0u, p);
    (*(NPtr<s16>)(rec + 0xA)) = hud_t(0x807847FCu, p);
    rrm_sprite.ax = rrm_sprite.ay = 0.0f;
    rrm_sprite.r = rrm_sprite.g = rrm_sprite.b = rrm_sprite.a = 0xFF;
    rrm_sprite.x = hud_t(0x807847F0u, p); rrm_sprite.y = hud_t(0x807847FCu, p); rrm_sprite.sx = 1.0f; rrm_sprite.sy = 1.0f;
    func_800DC85C(0x8016BB70u + bone, 0x8016D7F0u + part, (u32)&rrm_sprite);
    rrm_sprite.x = hud_t(0x80784808u, p); rrm_sprite.y = hud_t(0x80784814u, p); rrm_sprite.sx = 0.95f; rrm_sprite.sy = 0.6f;
    func_800DC85C(0x80175390u + bone, 0x80176F10u + part, (u32)&rrm_sprite);
    (*(NPtr<u8>)(0x8016DE70u + (u32)s)) = 0x14;
    rrm_sprite.x = hud_t(0x807847D8u, p); rrm_sprite.y = hud_t(0x807847FCu, p); rrm_sprite.sx = 2.0f; rrm_sprite.sy = 1.0f;
    func_800DC85C(0x80170E90u + bone, 0x80172A10u + part, (u32)&rrm_sprite);
}

