static float qa_sin(float a) {
    const float pi = 3.14159265f;
    while ((NM_TICK(), (a > pi))) a -= 2.0f * pi;
    while ((NM_TICK(), (a < -pi))) a += 2.0f * pi;
    if (a > pi * 0.5f) a = pi - a; else if (a < -pi * 0.5f) a = -pi - a;
    float a2 = a * a;
    return a * (1.0f - a2 / 6.0f * (1.0f - a2 / 20.0f * (1.0f - a2 / 42.0f * (1.0f - a2 / 72.0f))));
}

