static int qa_fbad(u32 a) { return ((*(NPtr<u32>)(a)) & 0x7F800000u) == 0x7F800000u; }

static int qa_bs_back_grapple(int s) {
    u32 w = ((0x8017FEF0u + 8u) + 0x358u * (u32)(s));
    if (((*(NPtr<u32>)(w + 0x14)) & 0xFFFFu) != 80 || qa_fbad(w + 0xF4) || qa_fbad(w + 0xFC)) return 0;
    for (int v = 0; (NM_TICK(), ( v < nm_slots())); v++) {
        u32 vw = ((0x8017FEF0u + 8u) + 0x358u * (u32)(v)); u32 vst = (*(NPtr<u32>)(vw + 0x14)) & 0xFFFFu;
        if (v == s || (vst != 34 && vst != 35) || qa_fbad(vw + 0xF4) || qa_fbad(vw + 0xFC)) continue;
        float dx = (*(NPtr<float>)(vw + 0xF4)) - (*(NPtr<float>)(w + 0xF4)); float dz = (*(NPtr<float>)(vw + 0xFC)) - (*(NPtr<float>)(w + 0xFC));
        s32 df = ((*(NPtr<s32>)(vw + 0x104)) - (*(NPtr<s32>)(w + 0x104))) & 4095;
        if (dx * dx + dz * dz < 70.0f * 70.0f && (df < 341 || df > 4096 - 341)) return 1;
    }
    return 0;
}

