static int sel_picked(void) {
    int n = 0;
    for (u32 i = 0; (NM_TICK(), ( i < 50)); i++) { u16 id = (*(NPtr<u16>)(0x800A95A0u + i * 12u)); if (id && id < 0x1000) n++; }
    return n;
}


static int qr_pick_more(void) {
    static NShrunk<int, 0, 1> stage(nm_private_at(0x17471C, 1));   /* qr_pick_more.stage: shrunk to one byte by the mod compiler */ static NVar<int> tries(lift_mod_address(0, 0x174720)); /* (private: its N64 place) */ /* qr_pick_more.tries: the N64 size */ static NVar<int> had(lift_mod_address(0, 0x174724)); /* (private: its N64 place) */ /* qr_pick_more.had: the N64 size */
    if (stage == 0) { if (auto_pick((u16)qa_w[1]) == 1) { stage = 1; tries = 0; had = -1; qr_wait = 60; } return 1; }
    int made = (*(NPtr<s32>)(0x800BD948u));
    if (made < 0 || made > 50) made = sel_picked();
    if (made != had) { had = made; tries = 0; pick_steps = 0; }
    int e = made - 2; int want = 0;
    int comp_extra = lumberjack_armed() ? lumberjack_competitors() - 2 : 0;
    if (e < 0) e = 0;
    if (e < comp_extra) want = qa_w[2 + e];
    else if (e - comp_extra < 4) want = qa_lj_w[e - comp_extra];
    if (want > 0) { int r = auto_pick((u16)want); if (r >= 0) return 1; }
    if (++tries % 60 == 1) inject_press(0x0100);
    else if (tries % 60 == 30) inject_press(0x8000);
    return 1;
}

static void qa_regular_rumble(void);

static void qa_regular_frame(void);
void nm_entry() {
    qr_pick_more();
}
