static int menu_nav_raw(void) {
    int n = 0;
    if (plat_key_down(82)) n |= 1;
    if (plat_key_down(81)) n |= 2;
    if (plat_key_down(80)) n |= 4;
    if (plat_key_down(79)) n |= 8;
    if (plat_key_down(40)) n |= 16;
    if (plat_key_down(41) || plat_key_down(42)) n |= 32;
    for (int pl = 0; (NM_TICK(), ( pl < 2)); pl++) {
        u16 b = pad_prev[pl];
        if ((b & 0x0800) || pad_stick[pl][1] > 40) n |= 1;
        if ((b & 0x0400) || pad_stick[pl][1] < -40) n |= 2;
        if ((b & 0x0200) || pad_stick[pl][0] < -40) n |= 4;
        if ((b & 0x0100) || pad_stick[pl][0] > 40) n |= 8;
        if (b & (0x8000 | 0x1000)) n |= 16;
        if (b & 0x4000) n |= 32;
    }
    return n;
}

