static NVar<int> reg_goal(0); /* (private: its N64 place, bound by nm_bind) */

static int match_quittable(void) {
    if (!nm_arcade()) {
        if (reg_goal) return 0;
        if (match_running()) return (*(NPtr<u8>)(0x80151ED6u)) == 0;
        s32 st = (*(NPtr<s32>)(0x800A872Cu));
        return !in_menus() && (*(NPtr<s32>)(0x800457A0u)) == 0 && (*(NPtr<s16>)(0x800457A4u)) == 42 && st > 0 && st < 30;
    }
    if (phase != PLAY || goal != G_NONE) return 0;
    if (match_running()) return (*(NPtr<u8>)(0x80151ED6u)) == 0;
    s32 step = (*(NPtr<s32>)(0x800A872Cu));
    return !in_menus() && (*(NPtr<s32>)(0x800457A0u)) == 0 && (*(NPtr<s16>)(0x800457A4u)) == 42 && step > 0 && step < 30;
}

