void modrep_nat_810BBDF0(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    frame.keep(0x10, ctx->r16);
    nm_ctx = ctx;
    nm_810BBDF0::nm_entry();
}
