static void bind_begin(int dev, int row) {
    bind_chain = 0;
    if (row == 19 && dev == 0) { bind_chain = 1; row = 14; }
    int r = plat_bind_start(dev, row);
    if (r == 1) { bind_on = 1; bind_dev = dev; bind_row = row; return; }
    menu_note_show(r == 2 ? NPtr<char>(lift_mod_address(0, 0x94A13))
                          : dev >= 2 ? NPtr<char>(lift_mod_address(0, 0x94118)) : NPtr<char>(lift_mod_address(0, 0x9269E)));
}

