static void menu_cam_put(float x, float y, float z, u32 page) {
    static /*NM_PC_CONST*/ const u32 at[4] = { 0x80104478u, 0x80104490u, 0x801044A8u, 0x80104540u };
    for (int i = 0; (NM_TICK(), ( i < 4)); i++) {
        NPtr<float> p = (NPtr<float>)at[i];
        p[0] = x; p[1] = y; p[2] = z;
    }
    NPtr<float> l = (NPtr<float>)0x8010449Cu;
    l[0] = x; l[1] = y; l[2] = z + 500.0f;
    (*(NPtr<u32>)(0x801044D4u)) = page;
    dbg_menu_cam++;
}

