typedef float Mtx4[4][4];

static int special_on(u32 w) {
    u32 me = (w - ((0x8017FEF0u + 8u) - 8u)) / 0x358;
    for (int s = 0, slots = nm_slots(); (NM_TICK(), ( s < slots)); s++) {
        u32 o = ((0x8017FEF0u + 8u) - 8u) + (u32)s * 0x358;
        if ((u32)s == me || (*(NPtr<s16>)(o + 0xA0)) == -1) continue;
        if (((*(NPtr<u8>)(o + 0xEE)) & 6) && (*(NPtr<s32>)(o + 0x08)) == (s32)me) return 1;
    }
    return 0;
}

static NArr<u32> dbg_down_level(lift_mod_address(0, 0x174A70), 0x8);

s32 arcade_down_anim(u32 w, int on) {
    u32 face_down = (*(NPtr<u16>)(w + 0x80)) & 0x10; u32 alt = (*(NPtr<u16>)(w + 0x8A)) & 1;
    s32 base = face_down ? (alt ? 0x2fd5 : 0x2fbc) : (alt ? 0x2f7e : 0x2f79); s32 level = 0;
    if ((*(NPtr<u8>)(w + 0xEE)) & 4) {
        if (!face_down) base = alt ? 0x2f87 : 0x2f86;
        return base;
    }
    if ((*(NPtr<s32>)(w + 0x14)) != 0x4f) return base;
    s16 times = (*(NPtr<s16>)(w + 0xBE)); s16 hp = (*(NPtr<s16>)(w + 0xAA));
    if (times >= 0x1e) level = face_down ? 2 : 3;
    else if (times >= 0x16) level = 2;
    else if (times >= 0xf && hp >= 0x40) level = 1;
    else level = hp >= 0x80 ? 0 : hp >= 0x40 ? 1 : 2;
    dbg_down_level[0] = (u32)level;
    if (level && on && arcade_fast_getup() && !special_on(w)) level = 0;
    dbg_down_level[1] = (u32)level;
    return (s16)(base + level);
}

