static float fabs_f(float v) { return v < 0.0f ? -v : v; }

static float wx(u32 w) { return *(NPtr<float>)(w + 0x120); }

static float wz(u32 w) { return *(NPtr<float>)(w + 0x128); }

static int w_in(u32 w) { return (*(NPtr<s16>)(w + 0xA0)) != -1 && !((*(NPtr<u16>)(w + 0x94)) & 1); }

static int w_ring(u32 w) { return ((*(NPtr<u16>)(w + 0x82)) & 0x7FF) == 1; }

static int w_apron(u32 w) { return ((*(NPtr<u16>)(w + 0x82)) & 0x7FF) == 2; }

static int w_danger(u32 w) { return ((*(NPtr<u8>)(w + 0xEE)) & 0x01) != 0; }

static u32 wr(int s) { return ((0x8017FEF0u + 8u) - 8u) + (u32)s * 0x358; }

static float dist1(u32 a, u32 b) { return fabs_f(wx(a) - wx(b)) + fabs_f(wz(a) - wz(b)); }

static int rr_choose(int slot, u32 me, NPtr<int> danger) {
    int best = -1; int best_d = -1;
    float bs = 1e9f; float bd = 1e9f;
    for (int o = 0, n = nm_slots(); (NM_TICK(), ( o < n)); o++) {
        u32 w = wr(o);
        if (o == slot || !w_in(w) || (!w_ring(w) && !w_apron(w))) continue;
        float d = dist1(w, me);
        if (w_danger(w)) {
            float k = w_apron(w) ? d * 0.5f : d;
            if (k < bd) { bd = k; best_d = o; }
        } else if (w_ring(w)) {
            float k = (float)(*(NPtr<u16>)(w + 0xAE)) * 6.0f + d;
            if (k < bs) { bs = k; best = o; }
        }
    }
    *danger = best_d >= 0;
    return best_d >= 0 ? best_d : best;
}
