template <> struct NView<NM_SELF::RRPlan> {
    u32 nm_at;
    NFieldOf<decltype(NM_SELF::RRPlan::prey)>::type prey;
    NFieldOf<decltype(NM_SELF::RRPlan::phase)>::type phase;
    NFieldOf<decltype(NM_SELF::RRPlan::t)>::type t;
    NFieldOf<decltype(NM_SELF::RRPlan::cool)>::type cool;
    NFieldOf<decltype(NM_SELF::RRPlan::focus)>::type focus;
    NFieldOf<decltype(NM_SELF::RRPlan::hold)>::type hold;
    explicit NView(u32 x) : nm_at(x), prey(x + (u32)offsetof(NM_SELF::RRPlan, prey)), phase(x + (u32)offsetof(NM_SELF::RRPlan, phase)), t(x + (u32)offsetof(NM_SELF::RRPlan, t)), cool(x + (u32)offsetof(NM_SELF::RRPlan, cool)), focus(x + (u32)offsetof(NM_SELF::RRPlan, focus)), hold(x + (u32)offsetof(NM_SELF::RRPlan, hold)) {}
    NView* operator->() { return this; }
};

template <> struct NRef<NM_SELF::RRPlan> : NView<NM_SELF::RRPlan> {
    explicit NRef(u32 x) : NView<NM_SELF::RRPlan>(x) {}
    NPtr<NM_SELF::RRPlan> operator&() const { return NPtr<NM_SELF::RRPlan>(this->nm_at); }
    const NRef& operator=(const NRef& o) const { nm_copy_bytes(this->nm_at, o.nm_at, NSize<NM_SELF::RRPlan>::value); return *this; }
    const NRef& operator=(const NM_SELF::RRPlan& v) const { nm_assign(this->prey, v.prey); nm_assign(this->phase, v.phase); nm_assign(this->t, v.t); nm_assign(this->cool, v.cool); nm_assign(this->focus, v.focus); nm_assign(this->hold, v.hold); return *this; }
};


