static void scene_tree(u32 p0, int p1) { lift_call<void>(nm_ctx, ::nm_native_call_modfn_810C0020)(p0, p1); }   // (the original calls it: the stand-in)

static NArr<u32[3]> pos_good(lift_mod_address(0, 0x174B64), 0x48);

static void positions_keep(void) {
    s32 mode = (*(NPtr<s32>)(0x800457A0u));
    if (mode != -2 && mode != -6) return;
    for (u32 sl = 0; (NM_TICK(), ( sl < 6)); sl++) {
        u32 w = 0x8017FEF0u + 0x358u * sl;
        u16 id = (*(NPtr<u16>)(w + 0xA0));
        if (!id || id == 0xFFFF) continue;
        int bad = 0;
        for (u32 k = 0; (NM_TICK(), ( k < 3)); k++) { u32 u = (*(NPtr<u32>)(w + 0xFC + 4 * k)); if ((u & 0x7F800000u) == 0x7F800000u || (u & 0x7F800000u) >= 0x49800000u) bad = 1; }
        if (bad) { if (pos_good[sl][0] | pos_good[sl][1] | pos_good[sl][2]) for (u32 k = 0; (NM_TICK(), ( k < 3)); k++) (*(NPtr<u32>)(w + 0xFC + 4 * k)) = pos_good[sl][k]; }
        else for (u32 k = 0; (NM_TICK(), ( k < 3)); k++) pos_good[sl][k] = (*(NPtr<u32>)(w + 0xFC + 4 * k));
    }
}

void scene_world(u32 n) { positions_keep(); scene_tree(n, 0); }
void nm_entry(u32 arg0) {
    scene_world((u32)arg0);
}
