static float sqrt_f(float x) {
    if (x <= 0.0f) return 0.0f;
    float r = x > 1.0f ? x * 0.5f : 1.0f;
    for (int i = 0; (NM_TICK(), ( i < 20)); i++) r = 0.5f * (r + x / r);
    return r;
}

