    NFieldOf<decltype(NM_SELF::RRPlan::focus)>::type focus;
    NFieldOf<decltype(NM_SELF::RRPlan::hold)>::type hold;
    explicit NView(u32 x) : nm_at(x), prey(x + (u32)offsetof(NM_SELF::RRPlan, prey)), phase(x + (u32)offsetof(NM_SELF::RRPlan, phase)), t(x + (u32)offsetof(NM_SELF::RRPlan, t)), cool(x + (u32)offsetof(NM_SELF::RRPlan, cool)), focus(x + (u32)offsetof(NM_SELF::RRPlan, focus)), hold(x + (u32)offsetof(NM_SELF::RRPlan, hold)) {}
