static int mtx_bad(u32 m) {
    for (u32 i = 0; (NM_TICK(), ( i < 16)); i++) {
        u32 u = (*(NPtr<u32>)(m + 4 * i));
        if ((u & 0x7F800000u) == 0x7F800000u) return 1;
        if ((u & 0x7F800000u) >= 0x49800000u) return 1;
    }
    return 0;
}
s32 nm_entry(u32 arg0) {
    return (s32)mtx_bad((u32)arg0);
}
