static int story_mode(void) { return (bs_on ? 2 : 0) | 1 | (roster_removed_n() > 0 ? 4 : 0); }

static u16 story_map(u16 id, int mode) {
    if (mode & 2) {
        if (id == 0x005) return 0x201;
        if (id == 0x201) return (mode & 1) ? 0x205 : 0x308;
    } else if (!(mode & 1) && id == 0x201) return 0x308;
    return id;
}

u32 bigshow_stand_in(void) { return story_map(0x201, story_mode()); }
u32 nm_entry() {
    return (u32)bigshow_stand_in();
}
