static int plat_wrestler_video_count() { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_8111FD6C)(); }   // (the original calls it: the stand-in)
static void plat_wrestler_video_get(int p0, u32 p1) { lift_call<void>(nm_ctx, ::nm_native_call_modfn_8111FD88)(p0, p1); }   // (the original calls it: the stand-in)

static NArr<FolderVideo> folder_videos(lift_mod_address(0, 0x17B2E0), 0x300);

static NVar<int> folder_videos_read(0); /* (private: its N64 place, bound by nm_bind) */

static int folder_video_count(void) {
    if (folder_videos_read < 0) {
        int n = plat_wrestler_video_count();
        if (n > 64) n = 64;
        for (int i = 0; (NM_TICK(), ( i < n)); i++) plat_wrestler_video_get(i, (u32)&folder_videos[i]);
        folder_videos_read = n;
    }
    return folder_videos_read < 64 ? folder_videos_read : 64;
}

int media_folder_video(u32 id) {
    for (int i = 0, n = folder_video_count(); (NM_TICK(), ( i < n)); i++) if (folder_videos[i].id == id) return (58 + 2) + i;
    return -1;
}

