static NVar<int> want_bs(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> want_media(0); /* (private: its N64 place, bound by nm_bind) */

static int video_wanted(int v) {
    return want_media || (want_bs && v == 5) || (v >= 44 && arcade_extras_has(EXTRAS_NMPLUS));
}

int entrance_table_loaded(void) {
    for (u32 i = 0; (NM_TICK(), ( i < 4)); i++)
        if ((*(NPtr<u16>)(0x800F50D0u + 12u * i)) != 0x16u + i || (*(NPtr<u16>)(0x800F50D0u + 12u * i + 2)) != 0xF1F0u) return 0;
    return 1;
}

static void lists_init(void) {
    if (tv_list[1][0][0]) return;
    for (int v = 1; (NM_TICK(), ( v <= 57)); v++) {
        for (int i = 0; (NM_TICK(), ( i < 72)); i++) { tv_list[v][i][0] = tv_carrier[i]; tv_list[v][i][1] = i == 1 ? 0x0004 : 0x8004; }
        tv_list[v][72][0] = 0xFFFF; tv_list[v][72][1] = 0;
    }
}

void media_entrance_tables(void) {
    if (!entrance_table_loaded()) return;
    lists_init();
    u32 slot = 0x800F50D0u + 12u * 2;
    if (want_bs && (*(NPtr<u32>)(slot + 4)) != 0x405u) { orig_fx = (*(NPtr<u32>)(slot + 4)); (*(NPtr<u32>)(slot + 4)) = 0x405u; }
    else if (!want_bs && (*(NPtr<u32>)(slot + 4)) == 0x405u) (*(NPtr<u32>)(slot + 4)) = orig_fx;
    for (int v = 1; (NM_TICK(), ( v <= 57)); v++) {
        u32 at = (0x800F50CCu + 12u * (u32)(v)); u32 ours = (u32)tv_list[v];
        if (video_wanted(v)) { if ((*(NPtr<u32>)(at)) != ours) { tv_orig[v] = (*(NPtr<u32>)(at)); (*(NPtr<u32>)(at)) = ours; } }
        else if ((*(NPtr<u32>)(at)) == ours) (*(NPtr<u32>)(at)) = tv_orig[v];
    }
}

