static NArr<NMAnon_pend> pend(lift_mod_address(0, 0x1842F8), 0x80);

static NVar<int> n_pend(0); /* (private: its N64 place, bound by nm_bind) */

void media_file_pre(u32 file, u32 dest) {
    if (!active_video || !ram_ptr(dest) || !ram_ptr(dest + 4624)) return;
    int k = -1;
    for (int i = 0; (NM_TICK(), ( i < 72)); i++) if (tv_carrier[i] == file) { k = i; break; }
    if (k < 0) return;
    if (n_pend == 8) { for (int i = 1; (NM_TICK(), ( i < n_pend)); i++) pend[i - 1] = pend[i]; n_pend--; }
    pend[n_pend].dest = dest; pend[n_pend].age = 0; pend[n_pend].video = active_video; pend[n_pend].frame = k;
    n_pend++;
}

s32 roster_entrance_song(u32 id, s32 c);
void nm_entry(u32 arg0, u32 arg1) {
    media_file_pre((u32)arg0, (u32)arg1);
}
