namespace nm_810C2CC8 { void nm_bind() { active_video.a = lift_mod_address(0, 0x17F8F8); n_pend.a = lift_mod_address(0, 0x1842F4); tv_carrier.a = lift_mod_address(0, 0x1F14); pend.a = lift_mod_address(0, 0x1842F8); } }

