s32 media_winner_song(s32 n) {
    u32 f = (*(NPtr<u32>)(0x800A10ECu)); u32 more = (*(NPtr<u32>)(0x80194330u));
    if (((*(NPtr<u32>)(0x800A9950u)) & 0x100000u) && !(f & 1u)) return 0xA;
    if (n <= 0) return 0x16;
    s32 w = (f & 1u) ? 0 : -1;
    for (s32 i = 1; (NM_TICK(), ( i < n && i < 4)); i++) if (f & (1u << i)) w = i;
    for (s32 i = 4; (NM_TICK(), ( i < n && i < 36)); i++) if ((more >> (i - 4)) & 1u) w = i;
    if (w < 0) return 0x16;
    s32 id = (*(NPtr<s16>)(0x804DC500u + 2u * (u32)w)); s32 c = (*(NPtr<u8>)(0x804DC540u + (u32)w));
    if (id <= 0) return 0x16;
    s32 s = roster_entrance_song((u32)id, c);
    if ((u16)(s - 23) < (80 + 41 + 64) - 23) { song_asked(id, s); return (s32)(s16)s; }
    return 0x16;
}
