int media_slot_fx(u32 slot, NPtr<u32> fx) {
    if (slot < 58 || slot >= 58 + 41) return 0;
    *fx = ext_slot_fx[slot - 58];
    return 1;
}
s32 nm_entry(u32 arg0, P<u32> arg1) {
    return (s32)media_slot_fx((u32)arg0, NPtr<u32>(arg1.a));
}
