static u32 phys(u32 a) { return (a >= 0x80000000u && a < 0xC0000000u) ? (a & 0x1FFFFFFFu) : a; }

u32 themes_audio_dma(u32 addr, s32 len) {
    const int folder_theme = addr >= 0x10000000u && addr < 0x10000000u + ((u32)folder_themes_on << 24) ? (int)((addr - 0x10000000u) >> 24) : -1;
    const int silent = silent_on && addr >= 0x0F000000u && addr < 0x0F000000u + 0x01000000u;
    if (folder_theme < 0 && !silent && (addr < 0x04000000u || addr >= 0x04000000u + 0xF3A2E0u + 0x1000u)) {
        u32 b = (u32)plat_game_call(GF_AUDIO_DMA, addr, (u32)len, 0);
        if (!b) return phys(addr);
        if ((addr & 0xFF000000u) == 0xFF000000u) addr = (addr & 0x00FFFFFFu) + 0x140000u;
        return phys((*(NPtr<u32>)(b + 0x10)) + addr - (*(NPtr<u32>)(b + 0xC)));
    }
    if ((*(NPtr<u32>)(0x80098954u)) & 1) return 0;
    u32 dlen = (*(NPtr<u32>)(0x8008D2F4u)); u32 end = addr + (u32)len; u32 prev = 0; u32 b = (*(NPtr<u32>)(0x8008D2E0u));
    for (; (NM_TICK(), ( b)); b = (*(NPtr<u32>)(b + 0x4))) {
        u32 start = (*(NPtr<u32>)(b + 0xC));
        if (addr < start) break;
        if (start + dlen >= end) { (*(NPtr<u32>)(b + 0x8)) = 2; return phys((*(NPtr<u32>)(b + 0x10)) + addr - start); }
        prev = b;
    }
    b = (*(NPtr<u32>)(0x8008D2E4u));
    if (!b) { b = (*(NPtr<u32>)(0x8008D2E0u)); return b ? phys((*(NPtr<u32>)(b + 0x10))) : 0; }
    (*(NPtr<u32>)(0x8008D2E4u)) = (*(NPtr<u32>)(b + 0x4));
    if (prev) {
        u32 nx = (*(NPtr<u32>)(prev + 0x4));
        (*(NPtr<u32>)(b + 0x4)) = nx;
        if (nx) (*(NPtr<u32>)(nx + 0x0)) = b;
        (*(NPtr<u32>)(b + 0x0)) = prev;
        (*(NPtr<u32>)(prev + 0x4)) = b;
    } else {
        u32 first = (*(NPtr<u32>)(0x8008D2E0u));
        (*(NPtr<u32>)(b + 0x0)) = 0;
        (*(NPtr<u32>)(b + 0x4)) = first;
        if (first) (*(NPtr<u32>)(first + 0x0)) = b;
        (*(NPtr<u32>)(0x8008D2E0u)) = b;
    }
    u32 start = addr & ~1u; u32 off = start - (folder_theme >= 0 ? 0x10000000u + ((u32)folder_theme << 24) : 0x04000000u);
    (*(NPtr<u32>)(b + 0xC)) = start;
    (*(NPtr<u32>)(b + 0x8)) = 2;
    u32 buf = (*(NPtr<u32>)(b + 0x10));
    const u32 size = folder_theme >= 0 ? (u32)folder_themes[folder_theme].wave[4] << 24 | (u32)folder_themes[folder_theme].wave[5] << 16 | (u32)folder_themes[folder_theme].wave[6] << 8 | folder_themes[folder_theme].wave[7] : 0xF3A2E0u;
    u32 have = off < size ? size - off : 0;
    u32 n = dlen < have ? dlen : have;
    if (silent) n = 0;
    if (n && folder_theme >= 0) { NPtr<u8> from = (NPtr<u8>)plat_pack((int)folder_themes[folder_theme].pack) + off; for (u32 i = 0; (NM_TICK(), ( i < n)); i++) (*(NPtr<u8>)(buf + i)) = from[i]; }
    else if (n) plat_content_read(off, buf, n);
    dbg_theme_last_off = off;
    for (u32 i = n; (NM_TICK(), ( i < dlen)); i++) (*(NPtr<u8>)(buf + i)) = 0;
    dbg_theme_reads++;
    return phys(buf + addr - start);
}
u32 nm_entry(u32 arg0, s32 arg1) {
    return (u32)themes_audio_dma((u32)arg0, (s32)arg1);
}
