static void silent_wave(u32 wave) {
    for (u32 i = 0; (NM_TICK(), ( i < 0xD0)); i++) (*(NPtr<u8>)(wave + i)) = 0;
    (*(NPtr<u32>)(wave + 0x04)) = 0x10002u;
    (*(NPtr<u8>)(wave + 0x09)) = 1;
    (*(NPtr<u32>)(wave + 0x18)) = 2; (*(NPtr<u32>)(wave + 0x1C)) = 1;
    (*(NPtr<u32>)(wave + 0xA0)) = 0;
    (*(NPtr<u32>)(wave + 0xA4)) = 0x10002u / 9u * 16u;
    (*(NPtr<u32>)(wave + 0xA8)) = 0xFFFFFFFFu;
}

