static int attacking(s32 st) {
    return st != 0x01 && st != 0 && st != 0x30 && st != 0x2d && st != 0x4f && st != 0x31;
}

static int who_hurt(int v) {
    int best = -1;
    for (int s = 0; (NM_TICK(), ( s < n_slots)); s++) {
        if (s == v || sn[s].id < 0 || sn[s].gone) continue;
        u32 o = wr(s);
        int after = (*(NPtr<s32>)(o + 0x08)) == v;
        if (after && attacking((*(NPtr<s32>)(o + 0x14)))) return s;
        if (after && best < 0) best = s;
    }
    if (best < 0 && n_slots == 2) best = v ^ 1;
    return best;
}
s32 nm_entry(s32 arg0) {
    return (s32)who_hurt((int)arg0);
}
