static NArr<Seen> sn(lift_mod_address(0, 0x18A148), 0x680);

static NVar<int> n_slots(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> frames_in(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> last_sub_frames(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u32> vi_start(0); /* (private: its N64 place, bound by nm_bind) */

static int female(s16 id) { int g = (id >> 8) & 0xFF; return g == 7 || g == 8; }

static void say_move(int ev, int a, int b, int arg, u16 move) {
    int fa = a >= 0 && a < n_slots ? sn[a].id : -1; int fb = b >= 0 && b < n_slots ? sn[b].id : -1;
    u32 m = move == 0xFFFF ? 0xFFFFu : (u32)(move / 10);
    plat_comm_event(ev, fa, fb, (int)((u32)(arg & 0xFF) | ((fa >= 0 && female((s16)fa)) ? 0x100u : 0u) | (m << 16)));
}

static void say(int ev, int a, int b, int arg) { say_move(ev, a, b, arg, 0xFFFF); }

static void hit_done(int v) {
    NPtr<Seen> x = &sn[v];
    x->open = 0;
    int a = x->by; int d = x->dmg; int c = x->cls;
    if (a < 0) return;
    int special = sn[a].special;
    int ev;
    if (c == 9 || (special && d >= 18 && (c == 4 || c == 5 || c == 6 || c == 10)))
        ev = EV_FINISHER;
    else if (c == 5) ev = EV_SUBMISSION;
    else if (c == 6) ev = EV_AERIAL;
    else if (c == 8) ev = EV_REVERSAL;
    else if (sn[v].outside || sn[a].outside || c == 11) ev = d >= 5 ? EV_OUTSIDE_HIT : EV_STRIKE;
    else if (c == 4 || d >= 14) ev = EV_BIG_MOVE;
    else if (c == 2 || c == 10) ev = EV_STRIKE_BIG;
    else if (c == 3) ev = d >= 8 ? EV_BIG_MOVE : EV_GRAPPLE;
    else ev = EV_STRIKE;
    if (sn[a].aerial_wait > 0) { sn[a].aerial_hit = 1; sn[a].aerial_wait = 0; if (c != 9) ev = EV_AERIAL; }
    say_move(ev, a, v, d > 255 ? 255 : d, x->move);
    if (ev == EV_SUBMISSION) last_sub_frames = frames_in;
    NPtr<Seen> A = &sn[a];
    A->dealt += (s16)d; x->took += (s16)d; x->hits_back = 0;
    s32 now = (s32)((*(NPtr<u32>)(0x80057404u)) - vi_start);
    if (x->took >= 30 && x->dealt <= 4) x->beaten_at = now;
    if (now - A->beaten_at < 1200 && ++A->hits_back >= 3) {
        say(EV_COMEBACK, a, v, 0); A->beaten_at = -100000; A->hits_back = 0;
    } else if (A->dealt >= 30 && A->took <= 4 && now - A->dom_at > 900) {
        say(EV_DOMINATE, a, v, 0); A->dom_at = now;
    }
    x->down_wait = (ev == EV_STRIKE || ev == EV_STRIKE_BIG) ? 40 : 0;
}
