static int ext_total(void) {
    if (!folder_read) {
        folder_read = 1;
        int n = plat_wrestler_count();
        folder_total = n > 0 ? n : 0;
        staging = folder_total > ((256 - 102) - (4 + 1 + 37));
        for (int s = 0; (NM_TICK(), ( s < ((256 - 102) - (4 + 1 + 37)))); s++) seat_folder[s] = -1;
        folder_n = staging ? ((256 - 102) - (4 + 1 + 37)) : folder_total;
        for (int i = 0; (NM_TICK(), ( i < folder_n)); i++) seat_fill(i, i);
        if (staging) plat_seat_note(1, ((256 - 102) - (4 + 1 + 37)), folder_total, 0);
    }
    return (4 + 1 + 37) + (folder_n < 0 ? 0 : folder_n > ((256 - 102) - (4 + 1 + 37)) ? ((256 - 102) - (4 + 1 + 37)) : folder_n);
}

