static int folder_has_looks(int i) { return i >= 0 && i < folder_n && seat_folder[i] >= 0 && (folder_w[i][0x09] & 0x10u); }

NPtr<u8> roster_folder_key(u32 src, NPtr<int> photo) {
    if ((*(NPtr<u8>)(src)) != 0xF0u || (*(NPtr<u8>)(src + 1u)) != 0x46u || (*(NPtr<u8>)(src + 0x16u)) != 0x80u) return 0;
    const int i = (*(NPtr<u8>)(src + 2u)); const int c = (*(NPtr<u8>)(src + 3u)) & 3;
    if (i >= folder_n || seat_folder[i] < 0 || folder_has_looks(i)) return 0;
    *photo = (255 - (i));
    return folder_real_key[i][c];
}

