s32 modrep_nat_810C7944(recomp_context* ctx, u32 arg0) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    frame.keep(0x10, ctx->r16);
    nm_ctx = ctx;
    return nm_810C7944::nm_entry(arg0);
}
