static u32 table_struct(s32 ord, s32 c) { return (*(NPtr<u32>)(0x80047124u + 16u * (u32)ord + 4u * (u32)c)); }

s32 roster_id_to_ord(u32 id) {
    if ((id & 0xF00u) == 0xB00u) return (s32)id - 0xAAD;
    for (s32 o = 0; (NM_TICK(), ( o < 0x54)); o++) if ((*(NPtr<u16>)(table_struct(o, 0))) == id) return o;
    int k = ext_of_id(id);
    return k >= 0 ? 102 + k : 0;
}

