static NArr<u16> rm_id(lift_mod_address(0, 0x1F69E4), 0xA8);

static NVar<int> rm_n(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> rm_qa(lift_mod_address(0, 0x12E528));

static void rm_read(void) {
    if (rm_n >= 0) return;
    rm_n = 0;
    const int n = plat_removed_count();
    for (int i = 0; (NM_TICK(), ( i < n && rm_n < 0x54)); i++) { const int id = plat_removed_get(i); if (id > 0 && id < 0x1000) rm_id[rm_n++] = (u16)id; }
    rm_qa = (int)plat_config(NPtr<char>(lift_mod_address(0, 0x93B8D)), 0);
}

static int rm_listed(u32 id) { for (int k = 0; (NM_TICK(), ( k < rm_n)); k++) if (rm_id[k] == (u16)id) return 1; return 0; }

int roster_id_removed(u32 id) {
    rm_read();
    if (rm_n <= 0) return 0;
    if (rm_listed(id)) return 1;
    return 0;
}

