static NVar<int> rm_len(0); /* (private: its N64 place, bound by nm_bind) */

void removal_s(NPtr<char> s) { while ((NM_TICK(), (*s && rm_len < (int)((u32)320) - 1))) rm_line[rm_len++] = *s++; rm_line[rm_len] = 0; }

void removal_num(s32 v) {
    NArr<char> b(nm_frame_base + 0x4);   /* char b[12], at the original's 0x4($sp) */
    int n = 0;
    u32 u = v < 0 ? (u32)-v : (u32)v;
    do { b[n++] = (char)('0' + u % 10u); u /= 10u; } while ((NM_TICK(), (u && n < 11)));
    if (v < 0) removal_s(NPtr<char>(lift_mod_address(0, 0xB0C5)));
    while ((NM_TICK(), (n))) { NArr<char> c(nm_frame_base + 0x0); c[0] = b [ -- n ]; c[1] = 0; removal_s(c); }
}

