static NVar<int> rm_qa(lift_mod_address(0, 0x12E528));

static void rm_read(void) {
    if (rm_n >= 0) return;
    rm_n = 0;
    const int n = plat_removed_count();
    for (int i = 0; (NM_TICK(), ( i < n && rm_n < 0x54)); i++) { const int id = plat_removed_get(i); if (id > 0 && id < 0x1000) rm_id[rm_n++] = (u16)id; }
    rm_qa = (int)plat_config(NPtr<char>(lift_mod_address(0, 0x93B8D)), 0);
}

int roster_removed_n(void) { rm_read(); return rm_n; }

static int box_removed(u16 id, s32 o) {
    if (roster_removed_n() <= 0) return 0;
    if (roster_id_removed(id)) return 1;
    return o == 14 && !bigshow_is_on() ? roster_id_removed(0x205) : 0;
}

