static NPtr<ExtWrestler> ext_w(int k) { return k >= (4 + 1) ? &ext_late[k - (4 + 1)] : &ext_wrestlers[k]; }

static u16 ext_id(int k) { return ext_is_folder(k) ? (u16)folder_u16(k, 0x00) : k == 4 ? 0x205 : ext_w(k)->id; }
static int ext_wanted(int p0) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810C8744)(p0); }   // (the original calls it: the stand-in)

static int ext_index(s32 ord) {
    u32 k = (u32)(ord - 102);
    if (!(k < (u32)ext_total() && ext_wanted((int)k))) return -1;
    if (ext_is_folder((int)k)) seat_used[k - (4 + 1 + 37)] = seat_tick;
    return (int)k;
}

