u32 roster_ord_to_id(s32 ord) {
    if ((u32)(ord - 0x54) < 0x12) return (u32)(ord + 0xAAD);
    if ((u32)(ord - 1) < 0x53) return (*(NPtr<u16>)(table_struct(ord, 0)));
    int k = ext_index(ord);
    return k >= 0 ? ext_id(k) : 0;
}

