static u32 match_entry(u32 id, s32 c) {
    u32 i = func_8000A690(id, (u32)c);
    if ((*(NPtr<u16>)(0x800BD4D0u + 2u * i)) == (u16)id) return i;
    for (u32 k = 0; (NM_TICK(), ( k < 0x65u)); k++) if ((*(NPtr<u16>)(0x800BD4D0u + 2u * k)) == (u16)id) return k;
    return i;
}

s32 roster_entrance_song(u32 id, s32 c) {
    s32 us = media_user_song(id);
    if (us >= 0) return us;
    if (!(*(NPtr<u32>)(0x80047E90u))) return (s8)(*(NPtr<u8>)(0x80097FE0u + 0x114u * match_entry(id, c)));
    u32 slot = (*(NPtr<u8>)(roster_record(roster_id_to_ord(id), c) + 0x4Bu));
    s32 s = media_slot_song(slot);
    return s >= 0 ? s : (s16)(*(NPtr<u16>)(0x800F50D0u + 12u * slot));
}

extern int arena_current(void);

u32 roster_record(s32 ord, s32 c) {
    u32 caw = (*(NPtr<u32>)(0x80047E98u));
    if ((u32)(ord - 0x54) < 0x12 && caw) return caw + (u32)(((ord - 0x54) * 4 + (c & 3)) * 0x4E);
    int k = ext_index(ord);
    if (k >= 0) return (u32)ext_rec[k][c & 3];
    u32 base = (*(NPtr<u32>)(0x80047E90u));
    if (ord < 1 || !base || ord >= 0x55) return 0x80069670u;
    return base + (u32)((ord * 4 + (c & 3)) * 0x4E);
}

