u32 modrep_nat_810C9924(recomp_context* ctx, s32 arg0, s32 arg1) {
    LiftFrame frame(ctx, 0x10);
    frame.keep(0xC, ctx->r31);
    frame.keep(0x8, ctx->r18);
    frame.keep(0x4, ctx->r17);
    frame.keep(0x0, ctx->r16);
    nm_ctx = ctx;
    return nm_810C9924::nm_entry(arg0, arg1);
}
