u32 roster_record(s32 ord, s32 c) {
    u32 caw = (*(NPtr<u32>)(0x80047E98u));
    if ((u32)(ord - 0x54) < 0x12 && caw) return caw + (u32)(((ord - 0x54) * 4 + (c & 3)) * 0x4E);
    int k = ext_index(ord);
    if (k >= 0) return (u32)ext_rec[k][c & 3];
    u32 base = (*(NPtr<u32>)(0x80047E90u));
    if (ord < 1 || !base || ord >= 0x55) return 0x80069670u;
    return base + (u32)((ord * 4 + (c & 3)) * 0x4E);
}

