u32 roster_moves(s32 ord) {
    u32 caw = (*(NPtr<u32>)(0x80047E9Cu));
    if ((u32)(ord - 0x54) < 0x12 && caw) return caw + (u32)((ord - 0x54) * 0xD8);
    int k = ext_index(ord);
    if (k >= 0) return (u32)ext_moves[k];
    u32 base = (*(NPtr<u32>)(0x80047E94u));
    if (ord < 1 || !base || ord >= 0x55) return 0x800696C0u;
    return base + (u32)(ord * 0xD8);
}

