static s32 stock_ord_of(u32 id) {
    if (id == 0x205) return 14;
    for (s32 o = 1; (NM_TICK(), ( o < 0x54)); o++) if ((*(NPtr<u16>)(table_struct(o, 0))) == id) return o;
    return 0;
}

static void stock_read(void) {
    if (stock_n >= 0) return;
    stock_n = 0;
    for (int o = 0; (NM_TICK(), ( o < 0x54)); o++) stock_of_ord[o] = -1;
    const int n = plat_stock_count();
    for (int i = 0; (NM_TICK(), ( i < n && stock_n < 0x54)); i++) {
        NPtr<u8> w = stock_w[stock_n];
        plat_stock_get(i, (u32)w);
        const u32 id = (u32)w[0x00] << 8 | w[0x00 + 1];
        const s32 o = stock_ord_of(id);
        if (o <= 0 || stock_of_ord[o] >= 0) { plat_stock_note(i, 6, 0, 0, id); continue; }
        stock_of_ord[o] = (s8)stock_n;
        stock_exe_i[stock_n] = (u8)i;
        stock_n++;
    }
    stock_twin = (int)plat_config(NPtr<char>(lift_mod_address(0, 0x932DD)), 0);
}

