static void put_str(u32 dst, NPtr<char> s, int size) {
    int i = 0;
    for (; (NM_TICK(), ( s[i] && i < size - 1)); i++) (*(NPtr<u8>)(dst + (u32)i)) = (u8)s[i];
    for (; (NM_TICK(), ( i < size)); i++) (*(NPtr<u8>)(dst + (u32)i)) = 0;
}

static void ext_build(int k, int c, u32 rec) {
    NPtr<ExtWrestler> w = ext_w(k);
    put_str(rec + 0x00, w->name, 0x15);
    put_str(rec + 0x15, w->short_name, 0x0B);
    put_str(rec + 0x20, w->nick, 0x11);
    NPtr<u8> key = parts_costume_key(k >= (4 + 1) ? k - 1 : k, c);
    for (int i = 0; (NM_TICK(), ( i < 0x17)); i++) (*(NPtr<u8>)(rec + 0x31 + (u32)i)) = key[i];
    (*(NPtr<u16>)(rec + 0x48)) = w->weight;
    (*(NPtr<u8>)(rec + 0x4A)) = w->height;
    (*(NPtr<u8>)(rec + 0x4B)) = w->music[ext_media ? 1 : 0];
    (*(NPtr<u8>)(rec + 0x4C)) = w->video[ext_media ? 1 : 0];
}

