int roster_class(u16 id) {
    id &= 0x0FFFu;
    if (!id) return 0;
    const u32 c = plat_wrestler_class(id);
    if (c >= 1 && c <= 8) return (int)c;
    const u16 g = id >> 8;
    if (g == 7) return id == 0x701 ? 1 : 2;
    if (g == 8) return 2;
    if (id == 0x901 || id == 0x902) return 8;
    if (id == 0x903) return 6;
    if (id == 0x904) return 5;
    return 1;
}

