static int plat_rivals(u32 p0, u32 p1) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_8111FF94)(p0, p1); }   // (the original calls it: the stand-in)
static u32 variant_base_of(u16 p0) { return lift_call<u32>(nm_ctx, ::nm_native_call_modfn_810D8D60)(p0); }   // (the original calls it: the stand-in)

static u16 rv_man(u16 id) { const u16 b = (u16)variant_base_of(id); return b ? b : id; }
static int rv_names(u16 p0, u16 p1) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810CD244)(p0, p1); }   // (the original calls it: the stand-in)

int roster_rivals(u16 a, u16 b) {
    a &= 0x0FFFu; b &= 0x0FFFu;
    if (!a || !b || rv_man(a) == rv_man(b)) return 0;
    const u16 xa[2] = { a, rv_man(a) }; const u16 xb[2] = { b, rv_man(b) };
    int not_them = 0;
    for (int i = 0; (NM_TICK(), ( i < 2)); i++)
        for (int j = 0; (NM_TICK(), ( j < 2)); j++) {
            if ((i && xa[1] == xa[0]) || (j && xb[1] == xb[0])) continue;
            const int r = plat_rivals(xa[i], xb[j]);
            if (r > 0) return 1;
            if (r < 0) not_them = 1;
        }
    if (not_them) return 0;
    for (int i = 0; (NM_TICK(), ( i < 2)); i++) for (int j = 0; (NM_TICK(), ( j < 2)); j++) if (rv_names(xa[i], xb[j]) || rv_names(xb[j], xa[i])) return 1;
    return 0;
}

