static NArr<u16> rv_id(lift_mod_address(0, 0x1F7578), 0x200);

static NArr<u16[3]> rv_of(lift_mod_address(0, 0x1F7778), 0x600);

static NVar<int> rv_n(0); /* (private: its N64 place, bound by nm_bind) */

static u16 rv_man(u16 id) { const u16 b = (u16)variant_base_of(id); return b ? b : id; }

static int rv_names(u16 a, u16 b) {
    for (int i = 0; (NM_TICK(), ( i < rv_n)); i++) {
        if (rv_id[i] != a) continue;
        for (int k = 0; (NM_TICK(), ( k < 3)); k++) if (rv_of[i][k] && rv_man(rv_of[i][k]) == rv_man(b)) return 1;
    }
    return 0;
}

