static NVar<int> jp_len(0); /* (private: its N64 place, bound by nm_bind) */

static int jp_have(void) {
    if (jp_len < 0) {
        jp_len = plat_pages_pack(jp_pack, (8 + 32 * 36));
        if (jp_len < 8 || jp_pack[0] != 'P' || jp_pack[1] != 'G' || jp_pack[2] != 1 || jp_pack[3] == 0) jp_len = 0;
    }
    return jp_len > 0;
}

