u16 roster_stand_in(u32 id, int nth) {
    if (!pages_built) return 0;
    s32 o = roster_id_to_ord(id);
    if (id == 0x205) o = 14;
    int p0 = -1; int b0 = 0;
    for (int p = 0; (NM_TICK(), ( p < 12 && p0 < 0)); p++)
        for (int i = 0; (NM_TICK(), ( i < (int)(*(NPtr<u16>)(((u32)base_tab) + (u32)p * 0x38 + 0x24)) && i < 9)); i++)
            if ((s32)(*(NPtr<u16>)(((u32)base_tab) + (u32)p * 0x38 + 4u * (u32)i + 2)) == o) { p0 = p; b0 = i; break; }
    if (p0 < 0) { p0 = 0; b0 = -1; }
    for (int s = 0; (NM_TICK(), ( s < 12)); s++) {
        const u32 pg = ((u32)base_tab) + (u32)((p0 + s) % 12) * 0x38;
        const int n = (int)(*(NPtr<u16>)(pg + 0x24)) < 9 ? (int)(*(NPtr<u16>)(pg + 0x24)) : 9;
        for (int j = 0; (NM_TICK(), ( j < n)); j++) {
            const int i = s == 0 ? nm_rem((b0 + 1 + j), n) : j;
            const u16 c = (*(NPtr<u16>)(pg + 4u * (u32)i));
            const s32 co = (s32)(*(NPtr<u16>)(pg + 4u * (u32)i + 2));
            if (!c || co == o || co <= 0 || co > 64 || box_removed(c, co)) continue;
            if (nth-- == 0) return c;
        }
    }
    return 0;
}

