s32 roster_page_of(u32 id, int back) {
    for (int k = 0; (NM_TICK(), ( k < roster_pages_n)); k++) {
        int p = back ? roster_pages_n - 1 - k : k;
        u32 pg = page(p);
        for (int i = 0; (NM_TICK(), ( i < (int)(*(NPtr<u16>)(pg + 0x24)) && i < 9)); i++)
            if ((*(NPtr<u16>)(pg + 4u * (u32)i)) == (u16)id) return p << 8 | i;
    }
    return -1;
}

