static NArr<u16> rv_id(lift_mod_address(0, 0x1F7578), 0x200);

static NArr<u16[3]> rv_of(lift_mod_address(0, 0x1F7778), 0x600);

static NVar<int> rv_n(0); /* (private: its N64 place, bound by nm_bind) */

static int rv_port(u16 id) { return (id >= 0x0105 && id <= 0x0119) || (id >= 0x060D && id <= 0x060F) || id == 0x030B || id == 0x060B; }

static void rv_add(u16 id, u32 moves) {
    if (!id || id >= 0x1000 || rv_port(id) || rv_n >= 256) return;
    for (int i = 0; (NM_TICK(), ( i < rv_n)); i++) if (rv_id[i] == id) return;
    rv_id[rv_n] = id;
    for (u32 k = 0; (NM_TICK(), ( k < 3)); k++) rv_of[rv_n][k] = (u16)rel_get(moves + 0xB8u, 149u + 12u * k);
    rv_n++;
}

