static NVar<int> ring_slot_now(0); /* (private: its N64 place, bound by nm_bind) */

static void ring_get(int j, int k) { ring_slot_now = j; ring_want_k = k; gl_mode = 1; glayout_run(); gl_mode = 0; }

static int ring_page_for(int j, int shown, int g) {
    const int d = nm_rem((j - shown + ring_w + ring_half), ring_w) - ring_half;
    return nm_rem((nm_rem((g + d), ring_total) + ring_total), ring_total);
}

static void ring_fill(int shown, int g) {
    for (int j = 0; (NM_TICK(), ( j < ring_w)); j++) {
        const int k = ring_page_for(j, shown, g);
        if (ring_page[j] == k) continue;
        ring_get(j, k);
    }
    ring_shown = shown;
}

static int ring_layout(void) {
    gl_mode = 0;
    ring_total = glayout_run();
    if (!ring_total) return 0;
    for (u32 i = 0; (NM_TICK(), ( i < 32 * 0x38)); i += 4) (*(NPtr<u32>)(((u32)roster_pages_tab) + i)) = 0;
    for (int p = 0; (NM_TICK(), ( p < 32)); p++) roster_pages_flags[p] = 0;
    for (int j = 0; (NM_TICK(), ( j < 32)); j++) ring_page[j] = -1;
    ring_w = staging ? 7 : (32 - 1);
    ring_half = ring_w / 2;
    if (ring_total <= ring_w) {
        for (int k = 0; (NM_TICK(), ( k < ring_total)); k++) ring_get(k, k);
        roster_pages_n = ring_total;
        ring_on = 0;
        return 1;
    }
    roster_pages_n = ring_w;
    ring_on = 1;
    ring_fill(0, 0);
    plat_seat_note(5, ring_w, ring_total, 0);
    return 1;
}

