static int live_n(int p0) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810DA008)(p0); }   // (the original calls it: the stand-in)
static u32 live_at(int p0, int p1) { return lift_call<u32>(nm_ctx, ::nm_native_call_modfn_810DA0F8)(p0, p1); }   // (the original calls it: the stand-in)

static int taken(u16 id, int c) {
    if ((u32)c >= 4) return 0;
    int once = ((*(NPtr<u32>)(0x8015B80Cu)) & 0x80u) != 0;
    for (u32 i = 0; (NM_TICK(), ( i < 50)); i++) {
        u32 p = 0x800A95A0u + 12u * i;
        if ((*(NPtr<u16>)(p)) != id) continue;
        if ((*(NPtr<u8>)(p + 2)) == (u32)c || once) return 1;
    }
    return 0;
}
static int first_free(u16 p0) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810D9D40)(p0); }   // (the original calls it: the stand-in)

static int live_index(int f, u16 id, int c) {
    for (int j = 0, n = live_n(f); (NM_TICK(), ( j < n)); j++) { const u32 v = live_at(f, j); if (var_id(v) == id && var_look(v) == c) return j; }
    return -1;
}
static void say_variant(int p0, int p1, int p2, u32 p3) { lift_call<void>(nm_ctx, ::nm_native_call_modfn_810DA20C)(p0, p1, p2, p3); }   // (the original calls it: the stand-in)

static int live_index(int f, u16 id, int c);
static int box_family(u16 p0, u32 p1) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810D9C0C)(p0, p1); }   // (the original calls it: the stand-in)

s32 sel_type_step(u32 id, s32 c, s32 dir, u32 row) {
    const int f = box_family((u16)id, row);
    if (f < 0) {
        if (first_free((u16)id) < 0) return c;
        for (int s = c + dir; (NM_TICK(), true); s += dir) {
            if (s > 3) s = 0;
            if (s < 0) s = 3;
            if (s == c) return c;
            if (!taken((u16)id, s)) return s;
        }
    }
    const int total = live_n(f);
    int at = live_index(f, (u16)id, c & 3);
    if (at < 0) for (int j = 0; (NM_TICK(), ( j < total && at < 0)); j++) if (var_id(live_at(f, j)) == (u16)id) at = j;
    if (at < 0) at = 0;
    for (int s = 1; (NM_TICK(), ( s < total)); s++) {
        const int q = nm_rem((nm_rem((at + dir * s), total) + total), total);
        const u32 v = live_at(f, q);
        const u16 m = var_id(v);
        const int mc = var_look(v);
        if (taken(m, mc)) continue;
        if (m != (u16)id) {
            (*(NPtr<u16>)(row + 0x62u)) = m;
            (*(NPtr<s32>)(0x8015B1ACu)) = 0;
            (*(NPtr<s32>)(0x8015B9E0u)) = 0x401;
        }
        say_variant(f, q, total, v);
        return mc;
    }
    return c;
}

