static int sel_family(u16 p0) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810DBE30)(p0); }   // (the original calls it: the stand-in)

static int taken(u16 id, int c) {
    if ((u32)c >= 4) return 0;
    int once = ((*(NPtr<u32>)(0x8015B80Cu)) & 0x80u) != 0;
    for (u32 i = 0; (NM_TICK(), ( i < 50)); i++) {
        u32 p = 0x800A95A0u + 12u * i;
        if ((*(NPtr<u16>)(p)) != id) continue;
        if ((*(NPtr<u8>)(p + 2)) == (u32)c || once) return 1;
    }
    return 0;
}

static int first_free(u16 id) {
    const int f = sel_family(id);
    if (f < 0) { for (int c = 0; (NM_TICK(), ( c < 4)); c++) if (!taken(id, c)) return c; return -1; }
    for (int j = 0, n = live_n(f); (NM_TICK(), ( j < n)); j++) { const u32 v = live_at(f, j); if (var_id(v) == id && !taken(id, var_look(v))) return var_look(v); }
    return -1;
}

static int live_index(int f, u16 id, int c);

