namespace nm_810DA0F8 { u32 nm_entry(s32 arg0, s32 arg1); }
u32 modrep_nat_810DA0F8(recomp_context* ctx, s32 arg0, s32 arg1) {
    LiftFrame frame(ctx, 0x38);
    frame.keep(0x34, ctx->r31);
    frame.keep(0x30, ctx->r23);
    frame.keep(0x2C, ctx->r22);
    frame.keep(0x28, ctx->r21);
    frame.keep(0x24, ctx->r20);
    frame.keep(0x20, ctx->r19);
    frame.keep(0x1C, ctx->r18);
    frame.keep(0x18, ctx->r17);
    frame.keep(0x14, ctx->r16);
    nm_ctx = ctx;
    return nm_810DA0F8::nm_entry(arg0, arg1);
}
