int variant_shown_look(u16 id, int look) {
    const u32 h = id && id < 0x1000 ? plat_hidden(id) : 0;
    if (!(h & (1u << (look & 3)))) return look;
    for (int c = 0; (NM_TICK(), ( c < 4)); c++) if (!(h & (1u << c))) return c;
    return look;
}
