static int live_n(int p0) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810DA008)(p0); }   // (the original calls it: the stand-in)
static u32 live_at(int p0, int p1) { return lift_call<u32>(nm_ctx, ::nm_native_call_modfn_810DA0F8)(p0, p1); }   // (the original calls it: the stand-in)

static int sel_family(u16 id) {
    const int f = fam_of(id);
    if (f < 0 || !member_on(id)) return -1;
    const int n = live_n(f);
    if (n != 4) return f;
    for (int j = 0; (NM_TICK(), ( j < 4)); j++) { const u32 v = live_at(f, j); if (var_id(v) != id || var_look(v) != j) return f; }
    return -1;
}

static int live_index(int f, u16 id, int c);

void draw_gtext(NPtr<char> s, u32 style, int cx, int y, u32 rgba);
s32 nm_entry(s32 arg0) {
    return (s32)sel_family((u16)arg0);
}
