static NPtr<u8> photo_tlut(int p0) { return lift_call<NPtr<u8>>(nm_ctx, ::nm_native_call_modfn_810DC960)(p0); }   // (the original calls it: the stand-in)
static NPtr<u8> photo_ci4(int p0) { return lift_call<NPtr<u8>>(nm_ctx, ::nm_native_call_modfn_810DCCA8)(p0); }   // (the original calls it: the stand-in)

static const u8 tex_header[16] = { 'T', 'E', 'X', 0, 0x00, 0x40, 0x00, 0x40, 0x04, 0x02, 0x00, 0x10, 0, 0, 0, 0 };

static const u8 ci4_header[8] = { 0x3F, 0x3F, 0x00, 0x20, 0x00, 0x00, 0x06, 0x06 };
static u32 storylist_file(u32 p0, u32 p1) { return lift_call<u32>(nm_ctx, ::nm_native_call_modfn_81098C00)(p0, p1); }   // (the original calls it: the stand-in)

static u32 ext_file_own(u32 file, u32 dest) {
    { u32 n = announce_file(file, dest); if (n) return n; }
    { extern u32 storylist_file(u32 file, u32 dest); u32 n = storylist_file(file, dest); if (n) return n; }
    { int p = -1; int part = 0;
      if (file >= (0x4C03u + (u32)((100) - 100)) && file < (0x4C03u + (u32)((100 + 28) - 100))) p = 100 + (int)(file - (0x4C03u + (u32)((100) - 100)));
      else if (file >= (0x4C1Fu + 2u * (u32)((100) - 100)) && file < (0x4C1Fu + 2u * (u32)((100 + 28) - 100))) {
          u32 k = file - (0x4C1Fu + 2u * (u32)((100) - 100)); p = 100 + (int)(k >> 1); part = 1 + (int)(k & 1); }
      else if (file >= (0x7C00u + (u32)((128) - 128)) && file < (0x7C00u + (u32)((128 + 128) - 128))) p = 128 + (int)(file - (0x7C00u + (u32)((128) - 128)));
      else if (file >= (0x7C80u + 2u * (u32)((128) - 128)) && file < (0x7C80u + 2u * (u32)((128 + 128) - 128))) {
          u32 k = file - (0x7C80u + 2u * (u32)((128) - 128)); p = 128 + (int)(k >> 1); part = 1 + (int)(k & 1); }
      if (p >= 0) {
        if (!photo_tlut(p)) return 0;
        if (part == 0) {
            if (dest) {
                for (u32 i = 0; (NM_TICK(), ( i < 16)); i++) (*(NPtr<u8>)(dest + i)) = tex_header[i];
                for (u32 i = 0; (NM_TICK(), ( i < 32)); i++) (*(NPtr<u8>)(dest + 16 + i)) = photo_tlut(p)[i];
                for (u32 i = 0; (NM_TICK(), ( i < 2048)); i++) (*(NPtr<u8>)(dest + 48 + i)) = photo_ci4(p)[i];
            }
            return 2096;
        }
        if (part == 1) {
            if (dest) for (u32 i = 0; (NM_TICK(), ( i < 32)); i++) (*(NPtr<u8>)(dest + i)) = photo_tlut(p)[i];
            return 32;
        }
        if (dest) {
            for (u32 i = 0; (NM_TICK(), ( i < 8)); i++) (*(NPtr<u8>)(dest + i)) = ci4_header[i];
            for (u32 i = 0; (NM_TICK(), ( i < 2048)); i++) (*(NPtr<u8>)(dest + 8 + i)) = photo_ci4(p)[i];
        }
        return 2056;
      }
    }
    if (file >= 0x5000u && file < 0x5000u + 4504) {
        u32 i = file - 0x5000u;
        if (dest) plat_wmport_read(wmp_files[i][0], dest, wmp_files[i][1]);
        return wmp_files[i][1];
    }
    return parts_file(file, dest);
}

