#undef NM_SELF
#define NM_SELF game::nm_810DD218

template <> struct NView<NM_SELF::PartFile> {
    u32 nm_at;
    NFieldOf<decltype(NM_SELF::PartFile::id)>::type id;
    NFieldOf<decltype(NM_SELF::PartFile::size)>::type size;
    NFieldOf<decltype(NM_SELF::PartFile::data)>::type data;
    explicit NView(u32 x) : nm_at(x), id(x + (u32)offsetof(NM_SELF::PartFile, id)), size(x + (u32)offsetof(NM_SELF::PartFile, size)), data(x + (u32)offsetof(NM_SELF::PartFile, data)) {}
    NView* operator->() { return this; }
};

template <> struct NRef<NM_SELF::PartFile> : NView<NM_SELF::PartFile> {
    explicit NRef(u32 x) : NView<NM_SELF::PartFile>(x) {}
    NPtr<NM_SELF::PartFile> operator&() const { return NPtr<NM_SELF::PartFile>(this->nm_at); }
    const NRef& operator=(const NRef& o) const { nm_copy_bytes(this->nm_at, o.nm_at, NSize<NM_SELF::PartFile>::value); return *this; }
    const NRef& operator=(const NM_SELF::PartFile& v) const { nm_assign(this->id, v.id); nm_assign(this->size, v.size); nm_assign(this->data, v.data); return *this; }
};


