void modrep_nat_810DDCA8(recomp_context* ctx, s32 arg0) {
    LiftFrame frame(ctx, 0x30);
    frame.keep(0x2C, ctx->r31);
    frame.keep(0x28, ctx->r22);
    frame.keep(0x24, ctx->r21);
    frame.keep(0x20, ctx->r20);
    frame.keep(0x1C, ctx->r19);
    frame.keep(0x18, ctx->r18);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    nm_ctx = ctx;
    nm_810DDCA8::nm_entry(arg0);
}
