static NVar<u32> dbg_pal_skipped(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u32> dbg_pal_calls(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u32> dbg_pal_room(0); /* (private: its N64 place, bound by nm_bind) */

void pal_group_guard(u32 part, s32 tex, s32 pal, s32 at, s32 n, s32 shift, s32 z) {
    u32 p = (*(NPtr<u32>)(part + 0x24));
    dbg_pal_calls++;
    u32 ring = 0x807F2C80u + 16u * (dbg_pal_calls % 40u);
    (*(NPtr<u32>)(ring)) = part; (*(NPtr<u32>)(ring + 4)) = p; (*(NPtr<u32>)(ring + 8)) = (u32)at | (u32)n << 16; (*(NPtr<u32>)(ring + 12)) = 0xFFFFFFFFu;
    if (((u32)(p) >= 0x80000400u && (u32)(p) < 0xA0000000u) && at >= 0 && n > 0) {
        u32 room = 0x200u;
        for (u32 off = 0; (NM_TICK(), ( off < 0x210u)); off += 4)
            if ((*(NPtr<u32>)(p + off)) == 0xCAFE4ABEu) { room = off >= 12u ? off - 12u : 0; break; }
        (*(NPtr<u32>)(ring + 12)) = room;
        u32 end = 2u * (u32)(at & 0xFF) + 2u * (u32)(n & 0xFF);
        if (end > 0x200u) end = 0x200u;
        if (end > room) { dbg_pal_room++; dbg_pal_skipped++; return; }
    }
    func_8000CAF8(part, tex, pal, at, n, shift, z);
}
void nm_entry(u32 arg0, s32 arg1, s32 arg2, s32 arg3, s32 arg4, s32 arg5, s32 arg6) {
    pal_group_guard((u32)arg0, (s32)arg1, (s32)arg2, (s32)arg3, (s32)arg4, (s32)arg5, (s32)arg6);
}
