#undef NM_SELF
#define NM_SELF game::nm_810E2808

template <> struct NView<NM_SELF::LibMove> {
    u32 nm_at;
    NFieldOf<decltype(NM_SELF::LibMove::file)>::type file;
    NFieldOf<decltype(NM_SELF::LibMove::then_file)>::type then_file;
    NFieldOf<decltype(NM_SELF::LibMove::ground)>::type ground;
    NFieldOf<decltype(NM_SELF::LibMove::n)>::type n;
    explicit NView(u32 x) : nm_at(x), file(x + (u32)offsetof(NM_SELF::LibMove, file)), then_file(x + (u32)offsetof(NM_SELF::LibMove, then_file)), ground(x + (u32)offsetof(NM_SELF::LibMove, ground)), n(x + (u32)offsetof(NM_SELF::LibMove, n)) {}
    NView* operator->() { return this; }
};

template <> struct NRef<NM_SELF::LibMove> : NView<NM_SELF::LibMove> {
    explicit NRef(u32 x) : NView<NM_SELF::LibMove>(x) {}
    NPtr<NM_SELF::LibMove> operator&() const { return NPtr<NM_SELF::LibMove>(this->nm_at); }
    const NRef& operator=(const NRef& o) const { nm_copy_bytes(this->nm_at, o.nm_at, NSize<NM_SELF::LibMove>::value); return *this; }
    const NRef& operator=(const NM_SELF::LibMove& v) const { nm_assign(this->file, v.file); nm_assign(this->then_file, v.then_file); nm_assign(this->ground, v.ground); nm_assign(this->n, v.n); return *this; }
};


