static NArr<PortMove> port_moves(lift_mod_address(0, 0x7A18C), 0xB22);

static NArr<u16> port_moves_at(lift_mod_address(0, 0x7A144), 0x48);

s32 movex_qa_entry(s32 late, s32 k) {
    NArr<s32> e(nm_frame_base + 0x0);   /* s32 e[32], at the original's 0x0($sp) */ s32 n = 0;
    if (late < 0 || late >= 35) return -1;
    for (int i = port_moves_at[late]; (NM_TICK(), ( i < port_moves_at[late + 1] && n < 32)); i++) {
        const u16 id = port_moves[i].id;
        if (id <= 1 || port_moves[i].entry >= 140) continue;
        int seen = 0;
        for (int j = port_moves_at[late]; (NM_TICK(), ( j < i && !seen)); j++) seen = port_moves[j].id == id;
        if (!seen) e[n++] = port_moves[i].entry;
    }
    return n ? e[nm_rem((k < 0 ? 0 : k), n)] : -1;
}

