static u32 rec_flags(s32 s, s32 e);

static NArr<s16> chain_from(lift_mod_address(0, 0x204660), 0x40);

static NArr<s16> chain_to(lift_mod_address(0, 0x2046A0), 0x40);

s32 movex_qa_subs(s32 s, NPtr<s16> out, s32 max, int specials) {
    s32 n = 0;
    if (!1 || s < 0 || s >= 32) return 0;
    for (s32 e = 0; (NM_TICK(), ( e < 292 && n < max)); e++) {
        if ((*(NPtr<u16>)((0x804E34C0u + (u32)(s) * (548 * 2u) + 2u * (u32)(e)))) == 0 || (*(NPtr<u16>)((0x804E34C0u + (u32)(s) * (548 * 2u) + 2u * (u32)(e)))) == 0xFFFFu) continue;
        s32 c = e; s32 hold = 0;
        for (int k = 0; (NM_TICK(), ( k < 4 && !hold)); k++) {
            u32 f = rec_flags(s, c);
            hold = (f & 0x0400u) != 0;
            if (!(f & 0x1E00u) && c == chain_from[s] && chain_to[s]) { c = chain_to[s]; continue; }
            if (!(f & 0x1E00u)) break;
            c = 292 + (*(NPtr<u8>)((0x80547320u + (u32)(s) * 548 + (u32)(c))));
        }
        if (hold && (!specials || (rec_flags(s, e) & 0x8000u))) out[n++] = (s16)e;
    }
    return n;
}

static u32 rec_flags(s32 s, s32 e) { return (*(NPtr<u32>)((0x805507A0u + (u32)(s) * (548 * 36u) + 36u * (u32)(e)) + 0x20u)); }

