static NArr<s16> chain_wait(lift_mod_address(0, 0x2114C0), 0x40);

static NArr<s8> chain_man(lift_mod_address(0, 0x211500), 0x20);

static NArr<s8> chain_on(lift_mod_address(0, 0x211490), 0x20);

static NArr<s8> chain_tries(lift_mod_address(0, 0x211520), 0x20);

static NArr<u32> dbg_chain(lift_mod_address(0, 0x2114B0), 0x10);

s32 movex_chain_pick(u32 w, s32 owner, s32 entry) {
    s32 i = (*(NPtr<s16>)(w + 0x9E));
    if (i < 0 || i >= 32 || owner != i) return entry;
    if (chain_on[i]) {
        if ((*(NPtr<u32>)(w + 0x14)) != 70u) chain_on[i] = 0;
        else if (entry == 240) { chain_on[i] = 0; dbg_chain[2]++; return chain_to[i]; }
        else if (entry == 155 || entry == 156 || entry == 158 || (entry >= 236 && entry <= 250)) chain_on[i] = 0;
    }
    if (chain_from[i] && entry == chain_from[i]) {
        s32 m = (s32)(*(NPtr<u32>)(w + 0x8));
        if (m >= 0 && m < nm_slots() && m != i) { chain_wait[i] = 600; chain_man[i] = (s8)m; chain_tries[i] = 0; dbg_chain[0]++; }
    }
    return entry;
}

extern int plat_anim_meta(u32 file, u32 dst);
s32 nm_entry(u32 arg0, s32 arg1, s32 arg2) {
    return (s32)movex_chain_pick((u32)arg0, (s32)arg1, (s32)arg2);
}
