static NArr<s16> chain_wait(lift_mod_address(0, 0x2114C0), 0x40);

static NArr<s8> chain_man(lift_mod_address(0, 0x211500), 0x20);

static NArr<s8> chain_on(lift_mod_address(0, 0x211490), 0x20);

static NArr<s8> chain_tries(lift_mod_address(0, 0x211520), 0x20);

static NArr<u32> dbg_chain(lift_mod_address(0, 0x2114B0), 0x10);

void movex_chain_step(void) {
    for (int i = 0; (NM_TICK(), ( i < nm_slots())); i++) {
        if (chain_wait[i] <= 0) continue;
        u32 w = (0x8017FEF0u + 0x358u * (u32)(i)); u32 st = (*(NPtr<u32>)(w + 0x14));
        if ((*(NPtr<s16>)(w + 0x308)) != chain_from[i] || --chain_wait[i] <= 0) { chain_wait[i] = 0; dbg_chain[3]++; continue; }
        if (st != 1u && st != 2u) continue;
        u32 v = (0x8017FEF0u + 0x358u * (u32)(chain_man[i]));
        if (plat_game_call(GF_GROUND_GRAPPLE, w, v, 0x8000u)) { chain_wait[i] = 0; chain_on[i] = 1; dbg_chain[1]++; }
        else if (++chain_tries[i] >= 20) { chain_wait[i] = 0; dbg_chain[3]++; }
    }
}

extern int plat_anim_meta(u32 file, u32 dst);
void nm_entry() {
    movex_chain_step();
}
