s32 movex_anim(u32 w, s32 who) {
    s32 o = (*(NPtr<s8>)(w + 0x304));
    if (o >= 0 && o < 32 && mx_any[o]) {
        s32 e = (*(NPtr<s16>)(w + 0x308));
        if (e >= 0 && e < 548 && mx_file[o][e] && who >= 0 && who < (s32)mx_n[o][e]) return (s32)mx_file[o][e] + who;
    }
    return (*(NPtr<s16>)(0x8015A700u + (u32)(2 * (s32)(*(NPtr<s16>)(w + 0x30A))))) + 0x3322 + who;
}

extern int plat_anim_meta(u32 file, u32 dst);
s32 nm_entry(u32 arg0, s32 arg1) {
    return (s32)movex_anim((u32)arg0, (s32)arg1);
}
