namespace nm_810E4258 { s32 nm_entry(s32 arg0); }
s32 modrep_nat_810E4258(recomp_context* ctx, s32 arg0) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x1C, ctx->r31);
    frame.keep(0x18, ctx->r17);
    frame.keep(0x14, ctx->r16);
    nm_ctx = ctx;
    return nm_810E4258::nm_entry(arg0);
}
