static NArr<u8[40]> own_meta(lift_mod_address(0, 0x2115D0), 0x140);

static NVar<u32> own_meta_n(0); /* (private: its N64 place, bound by nm_bind) */

static u32 own_meta_of(s32 file) {
    if (file >= 0x2DD9 && file < 0x2DD9 + 0x169B) return 0;
    u32 m = (u32)own_meta[own_meta_n++ & 7u];
    return plat_anim_meta((u32)file, m) ? m : 0;
}

static u32 anim_hdr(s32 file) {
    { u32 m = own_meta_of(file); if (m) return m; }
    return (*(NPtr<u32>)(0x8006A220u)) + 4u * (u32)(file - 0x2DD9);
}

s32 anim_frames(s32 file) { return (*(NPtr<s16>)(anim_hdr((s16)file) + 2u)); }
s32 nm_entry(s32 arg0) {
    return (s32)anim_frames((s32)arg0);
}
