namespace nm_810E468C { void nm_entry(u32 arg0, s32 arg1); }
void modrep_nat_810E468C(recomp_context* ctx, u32 arg0, s32 arg1) {
    LiftFrame frame(ctx, 0x28);
    frame.keep(0x24, ctx->r31);
    frame.keep(0x20, ctx->r19);
    frame.keep(0x1C, ctx->r18);
    frame.keep(0x18, ctx->r17);
    frame.keep(0x14, ctx->r16);
    nm_ctx = ctx;
    nm_810E468C::nm_entry(arg0, arg1);
}
