static int plat_anim_meta(u32 p0, u32 p1) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_81120138)(p0, p1); }   // (the original calls it: the stand-in)

static NArr<u8[40]> own_meta(lift_mod_address(0, 0x2115D0), 0x140);

static NVar<u32> own_meta_n(0); /* (private: its N64 place, bound by nm_bind) */

static u32 own_meta_of(s32 file) {
    if (file >= 0x2DD9 && file < 0x2DD9 + 0x169B) return 0;
    u32 m = (u32)own_meta[own_meta_n++ & 7u];
    return plat_anim_meta((u32)file, m) ? m : 0;
}

static u32 anim_hdr(s32 file) {
    { u32 m = own_meta_of(file); if (m) return m; }
    return (*(NPtr<u32>)(0x8006A220u)) + 4u * (u32)(file - 0x2DD9);
}

static u32 anim_rec(s32 file) {
    { u32 m = own_meta_of(file); if (m) return m + 4u; }
    return (*(NPtr<u32>)(0x8006A224u)) + 36u * (u32)(file - 0x2DD9);
}

void anim_details(u32 out, s32 file) {
    file = (s16)file;
    if (file < 0x2DD9) return;
    u32 h = anim_hdr(file); u32 r = anim_rec(file);
    (*(NPtr<u32>)(out)) = ((*(NPtr<u16>)(h)) & 0x3FFu) << 2;
    (*(NPtr<u8>)(out + 4u)) = (u8)(*(NPtr<u16>)(h + 2u));
    (*(NPtr<u8>)(out + 7u)) = (u8)((*(NPtr<u16>)(h)) >> 10);
    (*(NPtr<u8>)(out + 5u)) = (u8)((*(NPtr<u8>)(r + 1u)) >> 7);
    (*(NPtr<u8>)(out + 6u)) = (u8)((*(NPtr<u8>)(r)) & 0xFu);
    (*(NPtr<u8>)(out + 8u)) = (*(NPtr<u8>)(r + 3u)); (*(NPtr<u8>)(out + 9u)) = (*(NPtr<u8>)(r + 4u));
    (*(NPtr<u8>)(out + 0xAu)) = (*(NPtr<u8>)(r + 0x12u)); (*(NPtr<u8>)(out + 0xBu)) = (*(NPtr<u8>)(r + 0x13u));
    for (u32 k = 0; (NM_TICK(), ( k < 8)); k++) (*(NPtr<u8>)(out + 0xCu + k)) = (*(NPtr<u8>)(r + 5u + k));
    (*(NPtr<u8>)(out + 0x14u)) = (*(NPtr<u8>)(r + 0x11u)); (*(NPtr<u8>)(out + 0x15u)) = (*(NPtr<u8>)(r + 0x10u));
    (*(NPtr<u8>)(out + 0x16u)) = (*(NPtr<u8>)(r + 2u));
    (*(NPtr<u8>)(out + 0x17u)) = (u8)((*(NPtr<u8>)(r)) >> 4);
    (*(NPtr<u8>)(out + 0x18u)) = (*(NPtr<u8>)(r + 0xDu)); (*(NPtr<u8>)(out + 0x19u)) = (*(NPtr<u8>)(r + 0xEu)); (*(NPtr<u8>)(out + 0x1Au)) = (*(NPtr<u8>)(r + 0xFu));
}
void nm_entry(u32 arg0, s32 arg1) {
    anim_details((u32)arg0, (s32)arg1);
}
