void modrep_nat_810E48CC(recomp_context* ctx, s32 arg0, s32 arg1) {
    LiftFrame frame(ctx, 0x40);
    frame.keep(0x3C, ctx->r31);
    frame.keep(0x38, ctx->r30);
    frame.keep(0x34, ctx->r23);
    frame.keep(0x30, ctx->r22);
    frame.keep(0x2C, ctx->r21);
    frame.keep(0x28, ctx->r20);
    frame.keep(0x24, ctx->r19);
    frame.keep(0x20, ctx->r18);
    frame.keep(0x1C, ctx->r17);
    frame.keep(0x18, ctx->r16);
    nm_ctx = ctx;
    nm_810E48CC::nm_entry(arg0, arg1);
}
