static NArr<u32> dbg_as(lift_mod_address(0, 0x211548), 0x20);

void anim_stream(s32 n, s32 pri) {
    u32 p = 0x804B0000u + 192u * (u32)(s32)(s16)n;
    s32 left = (s32)(*(NPtr<u32>)(p + 0x14u));
    if (left == 0) return;
    u32 b = (*(NPtr<u8>)(p + 2u));
    s32 len = left < 0x62 ? left : 0x62;
    u32 buf = (*(NPtr<u32>)(p + 8u + 4u * b));
    func_80034310(buf, (u32)len);
    u32 m = p + 0x88u + 24u * b; u32 q = p + 0x58u + 24u * b; u32 rom = (*(NPtr<u32>)(p + 0x10u));
    (*(NPtr<u32>)(m + 4u)) = q;
    (*(NPtr<u8>)(m + 2u)) = (u8)pri;
    (*(NPtr<u32>)(m + 0xCu)) = rom;
    (*(NPtr<u32>)(m + 0x10u)) = (u32)len;
    (*(NPtr<u32>)(m + 8u)) = buf;
    dbg_as[0]++; dbg_as[1] = (u32)n; dbg_as[2] = rom; dbg_as[3] = (u32)left; dbg_as[4] = b; dbg_as[5] = (*(NPtr<u8>)(p + 3u));
    const int own = rom >= 0x60000000u && rom < 0x60000000u + 0x1E000000u;
    u32 pack = own ? 0u : (rom >= 0x7E000000u && rom < 0x7E000000u + 0x01000000u) ? plat_wmport_rom(rom - 0x7E000000u) : 1u;
    if (!pack) {
        dbg_as[6]++; dbg_as[7] = rom;
        if (own) plat_anim_read(rom, buf, (u32)len);
        else plat_wmport_read(rom - 0x7E000000u, buf, (u32)len);
        osSendMesg(q, m, 0);
    } else {
        if (pack != 1u) (*(NPtr<u32>)(m + 0xCu)) = pack;
        while ((NM_TICK(), (osEPiStartDma(osCartRomInit(), m, 0) != 0))) { }
    }
    if ((*(NPtr<u8>)(p + 3u))) osRecvMesg(p + 0x58u + 24u * (b ^ 1u), 0, 1);
    (*(NPtr<u8>)(p + 2u)) = (u8)(b ^ 1u);
    (*(NPtr<u8>)(p + 3u)) = 1;
    (*(NPtr<u32>)(p + 0x10u)) = rom + (u32)len;
    (*(NPtr<u32>)(p + 0x14u)) = (u32)((*(NPtr<s32>)(p + 0x14u)) - len);
}
void nm_entry(s32 arg0, s32 arg1) {
    anim_stream((s32)arg0, (s32)arg1);
}
