u32 ann_listed(void) {
    u32 n = 0; s16 c = (*(NPtr<s16>)(0x800619B2u));
    for (s16 i = 0; (NM_TICK(), ( i < c && i < 8192)); i++) {
        u32 d = (*(NPtr<u32>)(0x805EA9A0u + (u32)i * 4));
        if (!((u32)(d) >= 0x80000400u && (u32)(d) < 0xA0000000u)) continue;
        u32 bone = (*(NPtr<u32>)(d + 4));
        for (int k = 0; (NM_TICK(), ( k < 2)); k++)
            if (ann[k].bones && bone >= ann[k].bones && bone < ann[k].bones + 0x1810u) n++;
    }
    return n;
}

