u32 announce_file(u32 file, u32 dest) {
    NPtr<u8> m; u32 n;
    if (file == 0xFFF0u) { m = ann_chair_top; n = ((u32)280); }
    else if (file == 0xFFF0u + 1) { m = ann_chair_legs; n = ((u32)552); }
    else return 0;
    if (dest) for (u32 i = 0; (NM_TICK(), ( i < n)); i++) (*(NPtr<u8>)(dest + i)) = m[i];
    return n;
}

