namespace nm_810E5FAC { void nm_entry(P<u32> arg0); }
void modrep_nat_810E5FAC(recomp_context* ctx, P<u32> arg0) {
    LiftFrame frame(ctx, 0x38);
    frame.keep(0x34, ctx->r31);
    frame.keep(0x30, ctx->r20);
    frame.keep(0x2C, ctx->r19);
    frame.keep(0x28, ctx->r18);
    frame.keep(0x24, ctx->r17);
    frame.keep(0x20, ctx->r16);
    nm_ctx = ctx;
    nm_810E5FAC::nm_entry(arg0);
}
