void announce_watch(void) {
    if (!ann_built || ann_no_table || ann_broken || !((*(NPtr<u8>)(0x8007AC40u + 0x18)) & 0x80)) return;
    for (int i = 0; (NM_TICK(), ( i < 2)); i++)
        for (u32 b = 0; (NM_TICK(), ( b < 28)); b++) {
            u32 bone = ann[i].bones + b * 0xDC;
            if ((*(NPtr<u32>)(bone + 0x14))) (*(NPtr<u8>)(bone + 0x18)) = 0x80;
        }
    for (int i = 0; (NM_TICK(), ( i < 2)); i++)
        if (ann[i].chair_bones) for (u32 j = 0; (NM_TICK(), ( j < 2)); j++) (*(NPtr<u8>)(ann[i].chair_bones + j * 0xDC + 0x18)) = 0x80;
}
void nm_entry() {
    announce_watch();
}
