static void look_view(NPtr<float> cam, NPtr<float> view) {
    float ex = cam[1]; float ey = cam[2]; float ez = cam[3];
    float lx = cam[4] - ex; float ly = cam[5] - ey; float lz = cam[6] - ez; float n = sqrt_f(lx * lx + ly * ly + lz * lz);
    if (n < 1e-3f) return;
    lx /= n; ly /= n; lz /= n;
    float rx = ly * 0 - lz * 1; float ry = lz * 0 - lx * 0; float rz = lx * 1 - ly * 0;
    n = sqrt_f(rx * rx + ry * ry + rz * rz);
    if (n < 1e-3f) return;
    rx /= n; ry /= n; rz /= n;
    float ux = ry * lz - rz * ly; float uy = rz * lx - rx * lz; float uz = rx * ly - ry * lx;
    float v[16] = { rx, ux, -lx, 0, ry, uy, -ly, 0, rz, uz, -lz, 0,
                    -(rx * ex + ry * ey + rz * ez), -(ux * ex + uy * ey + uz * ez), lx * ex + ly * ey + lz * ez, 1 };
    for (int i = 0; (NM_TICK(), ( i < 16)); i++) view[i] = v[i];
}
void nm_entry(P<u32> arg0, P<u32> arg1) {
    look_view(NPtr<float>(arg0.a), NPtr<float>(arg1.a));
}
