int announce_where(NPtr<float> xyz) {
    if (!ann_built || !ann[0].bones || !ann[1].bones) return 0;
    for (u32 k = 0; (NM_TICK(), ( k < 3)); k++) {
        float a = *(NPtr<float>)(ann[0].bones + 0x5Cu + 48u + 4u * k); float b = *(NPtr<float>)(ann[1].bones + 0x5Cu + 48u + 4u * k);
        if (!(a == a) || !(b == b) || a < -1e5f || a > 1e5f || b < -1e5f || b > 1e5f) return 0;
        xyz[k] = 0.5f * (a + b);
    }
    return 1;
}
s32 nm_entry(P<u32> arg0) {
    return (s32)announce_where(NPtr<float>(arg0.a));
}
