u32 announce_owner(u32 node) {
    if (!node) return 0;
    for (int i = 0; (NM_TICK(), ( i < 2)); i++) {
        if (ann[i].bones && node >= ann[i].bones && node < ann[i].bones + 0x1810u) return (u32)(1 + i);
        if (ann[i].chair_bones && node >= ann[i].chair_bones && node < ann[i].chair_bones + 2 * 0xDCu) return (u32)(3 + i);
    }
    for (u32 k = 0; (NM_TICK(), ( k < (u32)nm_slot_span())); k++) if (node >= (0x804EBDC0u + (u32)(k) * 0x1810u) && node < (0x804EBDC0u + (u32)(k) * 0x1810u) + 0x1810u) return 0x10u + k;
    if (node >= 0x8007AC40u && node < 0x8007AC40u + 4 * 0xDCu) return 0x20;
    return 0;
}
u32 nm_entry(u32 arg0) {
    return (u32)announce_owner((u32)arg0);
}
