static void free_part(u32 part) {
    if (!(*(NPtr<u8>)(part))) return;
    (*(NPtr<u8>)(part)) = 0;
    if ((*(NPtr<u32>)(part + 0x10))) { func_8000093C((*(NPtr<u32>)(part + 0x10))); }
    else {
        if ((*(NPtr<u32>)(part + 0x14)) && !(*(NPtr<u32>)(part + 0x30))) func_8000093C((*(NPtr<u32>)(part + 0x14)));
        if ((*(NPtr<u32>)(part + 0x18)) && !(*(NPtr<u32>)(part + 0x30))) func_8000093C((*(NPtr<u32>)(part + 0x18)));
        if ((*(NPtr<u32>)(part + 0x1C)) && !(*(NPtr<u32>)(part + 0x30))) func_8000093C((*(NPtr<u32>)(part + 0x1C)));
    }
    (*(NPtr<u32>)(part + 0x10)) = (*(NPtr<u32>)(part + 0x14)) = (*(NPtr<u32>)(part + 0x18)) = (*(NPtr<u32>)(part + 0x1C)) = 0;
    if ((*(NPtr<u32>)(part + 0x20))) func_8000093C((*(NPtr<u32>)(part + 0x20)));
    if ((*(NPtr<u32>)(part + 0x24))) func_8000093C((*(NPtr<u32>)(part + 0x24)));
    (*(NPtr<u32>)(part + 0x20)) = (*(NPtr<u32>)(part + 0x24)) = 0;
}

