static void mtx_mul(NPtr<float> a, NPtr<float> b, NPtr<float> out) {
    NArr<float> t(nm_frame_base + 0x30);   /* float t[16], at the original's 0x30($sp) */
    for (int i = 0; (NM_TICK(), ( i < 4)); i++) for (int j = 0; (NM_TICK(), ( j < 4)); j++) {
        float s = 0; for (int q = 0; (NM_TICK(), ( q < 4)); q++) s += a[i * 4 + q] * b[q * 4 + j];
        t[i * 4 + j] = s;
    }
    for (int i = 0; (NM_TICK(), ( i < 16)); i++) out[i] = t[i];
}
void nm_entry(P<u32> arg0, P<u32> arg1, P<u32> arg2) {
    mtx_mul(NPtr<float>(arg0.a), NPtr<float>(arg1.a), NPtr<float>(arg2.a));
}
