static NArr<Pad> pads(lift_mod_address(0, 0x2130F0), 0xD0);

static NArr<u32> dbg_arc_last(lift_mod_address(0, 0x2131C0), 0x10);

static u32 vi_now(void) { return (*(NPtr<u32>)(0x80057404u)); }

static int w_in(int s) {
    u32 w = (((0x8017FEF0u + 8u) - 8u) + (u32)(s) * 0x358);
    return (*(NPtr<s16>)(w + 0xA0)) != -1 && !((*(NPtr<u16>)(w + 0x94)) & 1) && (*(NPtr<s32>)(w + 0x14)) != 0xA3 && !((*(NPtr<u8>)(w + 0xF1)) & 1);
}

static int slot_of_port(int port) {
    for (int s = 0, n = nm_slots(); (NM_TICK(), ( s < n)); s++)
        if ((*(NPtr<s32>)(0x8054B7A0u + 4u * (u32)s)) == port + 1 && w_in(s)) return s;
    return -1;
}

static u16 stick_dirs(s8 x, s8 y) {
    u16 b = 0;
    int ax = x < 0 ? -x : x; int ay = y < 0 ? -y : y;
    if (ax < 28 && ay < 28) return 0;
    if (ay * 5 > ax * 2) b |= y > 0 ? 0x0800 : 0x0400;
    if (ax * 5 > ay * 2) b |= x > 0 ? 0x0100 : 0x0200;
    return b;
}

static void act_begin(NPtr<Pad> p, u32 at) {
    p->act_vi = at;
    p->act = p->down_close ? ACT_PIN : p->ropes ? ACT_ROPES : ACT_CLEFT;
}

void arcctl_port(int port, u16 in, s8 sx, s8 sy, NPtr<u16> ob, NPtr<u8> ox, NPtr<u8> oy) {
    if (port < 0 || port > 3) return;
    NPtr<Pad> p = &pads[port];
    int me = p->slot;
    if (me < 0 || me != slot_of_port(port)) { p->prev = in; return; }
    u32 now = vi_now();
    u16 edge = (u16)(in & ~p->prev);
    p->prev = in;
    u16 out = (u16)(in & (0x1000 | 0x2000 | 0x0020 | 0x0008));
    s8 outx = 0; s8 outy = 0;
    u16 dirs = (u16)((in & (0x0800 | 0x0400 | 0x0200 | 0x0100)) | stick_dirs(sx, sy));
    const u16 DA = 0x0010 | 0x0002;
    out |= (u16)(in & (0x8000 | 0x4000));
    if (edge & 0x0001) {
        s8 fx = (s8)((dirs & 0x0100) ? 1 : (dirs & 0x0200) ? -1 : 0);
        s8 fy = (s8)((dirs & 0x0800) ? 1 : (dirs & 0x0400) ? -1 : 0);
        if (!fx && !fy) fy = 1;
        s8 m = (fx && fy) ? 56 : 80;
        p->synth = 1; p->synth_t = 0; p->synth_x = (s8)(fx * m); p->synth_y = (s8)(fy * m);
    }
    if (p->chord && !(in & DA)) p->chord = 0;
    if (!p->chord && (in & DA) == DA && (edge & DA)) {
        p->chord = 1; p->act = ACT_NONE; p->pin_out = 0;
        p->focus_held = 1; p->focus_dir_used = 0; p->focus_vi = now; p->last_dirs = dirs;
    }
    if (p->focus_held) {
        u16 newd = (u16)(dirs & ~p->last_dirs);
        if (dirs && (newd || (!p->focus_dir_used && now - p->focus_vi > 6))) {
            if (newd || !p->focus_dir_used) { p->req = FR_DIR; p->req_dirs = dirs; }
            p->focus_dir_used = 1;
        }
        p->last_dirs = dirs;
        if ((in & DA) != DA) {
            p->focus_held = 0;
            if (!p->focus_dir_used && now - p->focus_vi <= 24) p->req = FR_TAP;
        }
        dirs = 0;
    }
    out |= dirs;
    out |= (u16)(in & 0x0004);
    if ((in & 0x0010) && !p->down_first && !p->chord) out |= 0x0010 | 0x0020;
    if ((edge & 0x0002) && !p->chord) act_begin(p, now);
    if (p->act == ACT_PIN) {
        if (in & 0x0002) { if (now - p->act_vi >= 14) out |= 0x0010; }
        else { if (now - p->act_vi < 14) p->pin_out = 4; p->act = ACT_NONE; }
    } else if (p->act == ACT_ROPES) { if (in & 0x0002) out |= 0x0008; else p->act = ACT_NONE; }
    else if (p->act == ACT_CLEFT) { if (in & 0x0002) out |= 0x0002; else p->act = ACT_NONE; }
    if (p->pin_out) { out |= 0x0020; p->pin_out--; }
    if (p->synth) {
        if (p->synth_t < 4 - 1) { outx = p->synth_x; outy = p->synth_y; }
        if (++p->synth_t >= 4) p->synth = 0;
    }
    *ob = out; *ox = (u8)outx; *oy = (u8)outy;
    dbg_arc_last[port] = (u32)out | ((u32)(u8)outx << 16) | ((u32)(u8)outy << 24);
}
void nm_entry(s32 arg0, s32 arg1, s32 arg2, s32 arg3, P<u16> arg4, P<u8> arg5, P<u8> arg6) {
    arcctl_port((int)arg0, (u16)arg1, (s8)arg2, (s8)arg3, NPtr<u16>(arg4.a), NPtr<u8>(arg5.a), NPtr<u8>(arg6.a));
}
