static NArr<Pad> pads(lift_mod_address(0, 0x2130F0), 0xD0);

static u32 vi_now(void) { return (*(NPtr<u32>)(0x80057404u)); }
static int w_in(int p0) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810EC380)(p0); }   // (the original calls it: the stand-in)

static int w_lying(int s) { return ((*(NPtr<u8>)((((0x8017FEF0u + 8u) - 8u) + (u32)(s) * 0x358) + 0x8A)) & 0x40) != 0; }

static float wx(int s) { return *(NPtr<float>)((((0x8017FEF0u + 8u) - 8u) + (u32)(s) * 0x358) + 0x120); }

static float wy(int s) { return *(NPtr<float>)((((0x8017FEF0u + 8u) - 8u) + (u32)(s) * 0x358) + 0x124); }

static float wz(int s) { return *(NPtr<float>)((((0x8017FEF0u + 8u) - 8u) + (u32)(s) * 0x358) + 0x128); }

static int to_screen(float x, float y, float z, NPtr<float> sx, NPtr<float> sy) {
    NPtr<float> m = (NPtr<float>)0x80062BA8u;
    float rx = -x;
    float cx = rx * m[0] + y * m[4] + z * m[8] + m[12];
    float cy = rx * m[1] + y * m[5] + z * m[9] + m[13];
    float cw = rx * m[3] + y * m[7] + z * m[11] + m[15];
    if (cw < 1.0f) return 0;
    *sx = (cx / cw * 0.5f + 0.5f) * 640.0f;
    *sy = (0.5f - cy / cw * 0.5f) * 480.0f;
    return 1;
}

static NVar<float> dbg_arc_head(0); /* (private: its N64 place, bound by nm_bind) */

static int head_on_screen(int s, NPtr<float> sx, NPtr<float> sy) {
    float up = w_lying(s) ? 30.0f : dbg_arc_head;
    return to_screen(wx(s), wy(s) + up, wz(s), sx, sy);
}

static NArr<u32> dbg_arc_draw(lift_mod_address(0, 0x213208), 0x10);

void arcctl_draw(int port, u32 rgb) {
    if (port < 0 || port > 3) return;
    NPtr<Pad> p = &pads[port];
    dbg_arc_draw[port] = 1;
    if (!p->arrow_vi || p->slot < 0) return;
    u32 age = vi_now() - p->arrow_vi;
    dbg_arc_draw[port] = 2;
    if (age > 180) return;
    s32 t = (*(NPtr<s32>)((((0x8017FEF0u + 8u) - 8u) + (u32)(p->slot) * 0x358) + 0x08));
    dbg_arc_draw[port] = 3;
    if (t < 0 || t >= nm_slots() || t == p->slot || !w_in(t)) return;
    NVar<float> sx(nm_frame_base + 0x20); NVar<float> sy(nm_frame_base + 0x1C);
    dbg_arc_draw[port] = 4;
    if (!head_on_screen(t, &sx, &sy)) return;
    if (sx < -20.0f || sx > 660.0f || sy < -20.0f || sy > 500.0f) return;
    dbg_arc_draw[port] = 9 | (u32)(s32)sx << 8 | (u32)(s32)sy << 20;
    u32 a = 230;
    if (age > 180 - 36) a = 230u * (180 - age) / 36;
    int bob = age < 40 ? (int)((40 - age) / 8) : 0;
    int x = (int)sx; int y = (int)sy - 30 - bob;
    const int W = 13; const int H = 12;
    for (int r = 0; (NM_TICK(), ( r < H + 2)); r++) {
        int hw = W + 1 - nm_div((r * (W + 1)), (H + 1));
        if (hw < 1) hw = 1;
        draw_fill(x - hw, y + r - 1, hw * 2, 1, 0x10101000u | (a * 7 / 10));
    }
    for (int r = 0; (NM_TICK(), ( r < H)); r++) {
        int hw = W - nm_div((r * W), H);
        if (hw < 2) break;
        u32 c = r < 2 ? ((rgb | 0x404040u) & 0xFFFFFFu) : rgb;
        draw_fill(x - hw + 1, y + r, (hw - 1) * 2, 1, (c << 8) | a);
    }
}
void nm_entry(s32 arg0, u32 arg1) {
    arcctl_draw((int)arg0, (u32)arg1);
}
