static u32 ours(s32 p0) { return lift_call<u32>(nm_ctx, ::nm_native_call_modfn_810EC694)(p0); }   // (the original calls it: the stand-in)
static u32 lumberjack_caption(s32 p0) { return lift_call<u32>(nm_ctx, ::nm_native_call_modfn_81123054)(p0); }   // (the original calls it: the stand-in)

u32 story_card_text(s32 id) {
    { u32 lc = lumberjack_caption(id); if (lc) return lc; }
    u32 o = ours(id);
    if (o) return o;
    if ((u32)(id - 0xF0CE) < 0xFDu) return (*(NPtr<u32>)(0x800B0000u + (u32)id * 4u + 0x6F58u));
    for (u32 i = 0; (NM_TICK(), ( i < 15)); i++) {
        u32 e = 0x800F3938u + i * 6u;
        s32 first = (s32)(*(NPtr<u16>)(e));
        if (id < first || (s32)(*(NPtr<u16>)(e + 2)) < id) continue;
        return (u32)plat_game_call(GF_TEXT_BANK, (*(NPtr<u16>)(e + 4)), (u32)(id - first), 0);
    }
    return 0x800F3684u;
}

