namespace nm_810ECF28 { u32 nm_entry(s32 arg0); }
u32 modrep_nat_810ECF28(recomp_context* ctx, s32 arg0) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    frame.keep(0x10, ctx->r16);
    nm_ctx = ctx;
    return nm_810ECF28::nm_entry(arg0);
}
