u32 story_scene_text(s32 id) {
    u32 o = ours(id);
    if (o) return o;
    for (s32 i = 0; (NM_TICK(), ( i < 8)); i++) {
        u32 e = 0x80125CC4u + (u32)i * 6u;
        s32 first = (s32)(*(NPtr<u16>)(e));
        if (id < first || (s32)(*(NPtr<u16>)(e + 2)) < id) continue;
        if (i != (*(NPtr<s16>)(0x80106630u))) break;
        return (u32)plat_game_call(GF_SCENE_TEXT_BANK, (*(NPtr<u16>)(e + 4)), (u32)(id - first), 0);
    }
    return 0x80125CF4u;
}

