static u32 save_image(void) { u32 img = (*(NPtr<u32>)(0x80062C20u)); return (((u32)(img) >= 0x80000400u && (u32)(img) < 0xA0000000u)) ? img : 0; }

void story_save_swap(int before) {
    u32 img = save_image();
    if (before) {
        sv_swapped = 0;
        if (!pk || !sv_rec_img || img != sv_rec_img) return;
        copy((u32)sv_tmp, img + 0x6D5Cu, 0xC4u);
        copy(img + 0x6D5Cu, (u32)sv_rec, 0xC4u);
        sv_swapped = 1;
    } else if (sv_swapped) {
        if (img) copy(img + 0x6D5Cu, (u32)sv_tmp, 0xC4u);
        sv_swapped = 0;
    }
}

