static NVar<int> rt_n(0); /* (private: its N64 place, bound by nm_bind) */

static NArr<char[28]> rt_menu(lift_mod_address(0, 0x215400), 0x1C000);

static NArr<u8> rt_belt(lift_mod_address(0, 0x231400), 0x1000);

static NArr<u8> rt_pack(lift_mod_address(0, 0x232400), 0x100000);

void story_rescan(void) {
    int n = plat_story_scan();
    if (n > 4096) n = 4096;
    int k = 0;
    for (int i = 0; (NM_TICK(), ( i < n)); i++) {
        int b = plat_story_menu(i, rt_menu[k], (int)sizeof(char[28]));
        if (b < 0 || b > 7) continue;
        rt_menu[k][sizeof(char[28]) - 1] = 0;
        rt_belt[k] = (u8)b;
        k++;
    }
    rt_n = n > 0 ? k : 0;
}

static int rt_on(void) { if (rt_n < 0) story_rescan(); return rt_n > 0; }

int story_start_builtin(int i) {
    if (rt_on()) {
        if (i < 0 || i >= rt_n || plat_story_pack(i, rt_pack, (int)((u32)1048576)) <= 0) return 0;
        return story_start((u32)rt_pack);
    }
    return i >= 0 && i < 4 ? story_start((u32)story_packs[i].data) : 0;
}

enum { MS_TIME = 1, MS_HEALTH, MS_OUTSIDE, MS_HOLD, MS_FINISHER };

