static void apply_sets(u32 first, u32 n) {
    for (u32 i = 0; (NM_TICK(), ( i < n)); i++) {
        NPtr<SSet> t = (NPtr<SSet>)(pk_sets + sizeof(SSet) * (first + i));
        switch (t->kind) {
        case S_SET: if (t->a < 32) st_var[t->a] = t->b; break;
        case S_ADD: if (t->a < 32) st_var[t->a] += t->b; break;
        case S_ROLE_COPY:
            (*(NPtr<u16>)(0x80097EECu + 2u * (t->a & 7u))) = (*(NPtr<u16>)(0x80097EECu + 2u * ((u32)t->b & 7u)));
            (*(NPtr<u8>)(0x80097EFCu + (t->a & 7u))) = (*(NPtr<u8>)(0x80097EFCu + ((u32)t->b & 7u)));
            exp_clear(); resolve_slots();
            break;
        case S_ROLE_SET: (*(NPtr<u16>)(0x80097EECu + 2u * (t->a & 7u))) = (u16)t->b; (*(NPtr<u8>)(0x80097EFCu + (t->a & 7u))) = 0; exp_clear(); resolve_slots(); break;
        }
    }
}

