static int term(NPtr<SCond> p0, int p1, s32 p2) { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810F1BC4)(p0, p1, p2); }   // (the original calls it: the stand-in)

static int run_conds(u32 first, u32 n, int prog, int br, s32 rating) {
    NArr<u8> stk(nm_frame_base + 0x0);   /* u8 stk[16], at the original's 0x0($sp) */
    u32 sp = 0;
    for (u32 i = 0; (NM_TICK(), ( i < n)); i++) {
        NPtr<SCond> c = (NPtr<SCond>)(pk_conds + sizeof(SCond) * (first + i));
        if (!prog) { if (!term(c, br, rating)) return 0; continue; }
        if (c->kind == C_AND || c->kind == C_OR) {
            if (sp < 2) return 0;
            sp--;
            stk[sp - 1] = c->kind == C_AND ? (stk[sp - 1] && stk[sp]) : (stk[sp - 1] || stk[sp]);
        } else if (c->kind == C_NOT) {
            if (sp < 1) return 0;
            stk[sp - 1] = !stk[sp - 1];
        } else {
            if (sp >= 16) return 0;
            stk[sp++] = (u8)term(c, br, rating);
        }
    }
    return prog ? (sp == 1 && stk[0]) : 1;
}

