static NArr<u8> st_rec(lift_mod_address(0, 0x3326D0), 0x8);

static NVar<u16> st_retry_node(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<u16> st_retries(0); /* (private: its N64 place, bound by nm_bind) */

u32 story_branch(void) {
    u32 node = (*(NPtr<u32>)(0x80097F14u));
    u32 first = (*(NPtr<u16>)(node + 8));
    u32 hist = 0x80097ED0u + 0x3Eu + (*(NPtr<u8>)(0x80097ED0u)) * 10u;
    s32 rating = plat_game_call(GF_RATING, 0, 0, 0);
    if ((*(NPtr<u32>)(0x800A957Cu)) & 0x200u) plat_game_call(GF_HISTORY_RUMBLE, hist, 0, 0);
    else (*(NPtr<u8>)(hist + 9)) = (u8)rating;
    if (!pk) {
        u32 r = 0x800FA720u + first * 8u;
        for (; (NM_TICK(), ( (*(NPtr<u8>)(r)))); r += 8) if (game_cond((*(NPtr<u32>)(0x800F8DC4u + (*(NPtr<u8>)(r)) * 4u)), rating)) return r;
        return r;
    }
    st_res = (game_cond(1u, rating) ? 1u : 0u) | (game_cond(2u, rating) ? 2u : 0u) | (game_cond(4u, rating) ? 4u : 0u);
    for (u32 i = first; (NM_TICK(), ( i < ph->n_branches)); i++) {
        NPtr<SBranch> b = (NPtr<SBranch>)(pk_branches + sizeof(SBranch) * i);
        int last = !b->game_mask && !b->cond_n;
        if (!last && b->game_mask && !game_cond(b->game_mask, rating)) continue;
        if (!last && !our_conds(b, rating)) continue;
        our_sets(b);
        dbg_story_branch = i;
        if (!b->scene) {
            u32 sc = (*(NPtr<u16>)(node + 2));
            if (sc && sc <= ph->n_scenes) {
                u32 q = (*(NPtr<u16>)(pk_scenes + 6u * (sc - 1u) + 2u));
                while ((NM_TICK(), (q < ph->n_cmds && (*(NPtr<u8>)(pk_cmds + 4u * q)) != 0x00u))) q++;
                if (q < ph->n_cmds) (*(NPtr<u16>)(0x80097EEAu)) = (u16)q;
            }
        }
        st_rec[0] = 1; st_rec[1] = b->effect;
        st_rec[2] = (u8)((u16)b->money >> 8); st_rec[3] = (u8)b->money;
        u16 nx = b->next;
        if (!nx) {
            u16 cur = (*(NPtr<u16>)(0x80097ED4u));
            if (st_retry_node != cur) { st_retry_node = cur; st_retries = 0; }
            if (st_retries < ((*(NPtr<u8>)(node + 0xFu)) & 0xFu)) { st_retries++; nx = cur; }
            else (*(NPtr<u8>)(0x80097ED3u)) = 0xFF;
        } else st_retry_node = 0;
        st_rec[4] = (u8)(nx >> 8); st_rec[5] = (u8)nx;
        st_rec[6] = (u8)(b->scene >> 8); st_rec[7] = (u8)b->scene;
        return (u32)st_rec;
    }
    st_rec[0] = 0; st_rec[1] = 0; st_rec[2] = st_rec[3] = st_rec[4] = st_rec[5] = st_rec[6] = st_rec[7] = 0;
    return (u32)st_rec;
}

