#define NM_SELF game::nm_810F470C

template <> struct NView<NM_SELF::NMAnon_rm_preset> {
    u32 nm_at;
    NFieldOf<decltype(NM_SELF::NMAnon_rm_preset::used)>::type used;
    NFieldOf<decltype(NM_SELF::NMAnon_rm_preset::was)>::type was;
    NFieldOf<decltype(NM_SELF::NMAnon_rm_preset::now)>::type now;
    NFieldOf<decltype(NM_SELF::NMAnon_rm_preset::after)>::type after;
    explicit NView(u32 x) : nm_at(x), used(x + (u32)offsetof(NM_SELF::NMAnon_rm_preset, used)), was(x + (u32)offsetof(NM_SELF::NMAnon_rm_preset, was)), now(x + (u32)offsetof(NM_SELF::NMAnon_rm_preset, now)), after(x + (u32)offsetof(NM_SELF::NMAnon_rm_preset, after)) {}
    NView* operator->() { return this; }
};

template <> struct NRef<NM_SELF::NMAnon_rm_preset> : NView<NM_SELF::NMAnon_rm_preset> {
    explicit NRef(u32 x) : NView<NM_SELF::NMAnon_rm_preset>(x) {}
    NPtr<NM_SELF::NMAnon_rm_preset> operator&() const { return NPtr<NM_SELF::NMAnon_rm_preset>(this->nm_at); }
    const NRef& operator=(const NRef& o) const { nm_copy_bytes(this->nm_at, o.nm_at, NSize<NM_SELF::NMAnon_rm_preset>::value); return *this; }
    const NRef& operator=(const NM_SELF::NMAnon_rm_preset& v) const { nm_assign(this->used, v.used); nm_assign(this->was, v.was); nm_assign(this->now, v.now); nm_assign(this->after, v.after); return *this; }
};


