NPtr<void> memcpy(NPtr<void> d, NPtr<void> s, unsigned int n) {
    NPtr<u8> p = (NPtr<u8>)d;
    NPtr<u8> q = (NPtr<u8>)s;
    while ((NM_TICK(), (n--))) *p++ = *q++;
    return d;
}
u32 nm_entry(P<u32> arg0, P<u32> arg1, u32 arg2) {
    return memcpy(NPtr<void>(arg0.a), NPtr<void>(arg1.a), (unsigned int)arg2).a;
}
