static void panel_apply(int i);

static NVar<s32> tron_v(lift_mod_address(0, 0x3373CC));

static NVar<int> vid_k(0); /* (private: its N64 place, bound by nm_bind) */

static NVar<int> vid_left(0); /* (private: its N64 place, bound by nm_bind) */

static NShrunk<int, 0, 1> vid_ready(nullptr);   // (shrunk to one byte by the mod compiler)

static NShrunk<int, 0, 1> music_on(nullptr);   // (shrunk to one byte by the mod compiler)

static NVar<int> native_bits(lift_mod_address(0, 0x3373C4));

static NVar<int> ring_song_bits(0); /* (private: its N64 place, bound by nm_bind) */

static void music_off(void) {
    if (native_bits || ring_song_bits) { plat_entrance_media((u32)tron_stop_fade, 0, 0); native_bits = 0; ring_song_bits = 0; }
    tron_stop_fade = 0;
    music_on = 0;
}

int tron_music(int on) {
    int ent = (*(NPtr<s16>)(0x800457A4u)) == 42 && (*(NPtr<s32>)(0x800A872Cu)) >= 1 && (*(NPtr<s32>)(0x800A872Cu)) <= 29;
    if (on && ent) {
        s32 v = arcade_entrant_video();
        tron_v = v > 0 ? v : 0;
        music_on = 1; vid_k = -1; vid_left = 0; vid_ready = 0;
        s32 who = (*(NPtr<s32>)(0x80133B94u));
        native_bits = (who >= 0 && who < 4) ? plat_entrance_media((*(NPtr<u32>)(0x8053BCA0u + 4u * (u32)who)) & 0xFFFFu, 0, 1) : 0;
        return native_bits;
    }
    else if (!on) music_off();
    return 0;
}

