static NArr<NMAnon_tron_place> tron_place(lift_mod_address(0, 0x81CE0), 0x5A);

int tron_screen_place(int a, NPtr<float> xyz, NPtr<float> width) {
    for (u32 k = 0; (NM_TICK(), ( k < ((u32)90) / sizeof(NMAnon_tron_place))); k++) {
        if (tron_place[k].arena != a) continue;
        xyz[0] = tron_place[k].x; xyz[1] = tron_place[k].y; xyz[2] = tron_place[k].z; *width = tron_place[k].w;
        return 1;
    }
    return 0;
}

