static int tron_mode(void) {
    s32 mode = (*(NPtr<s32>)(0x800457A0u));
    if (dbg_tron_any) return (int)dbg_tron_any;
    if (tron_story_on()) return 2;
    s32 st = (*(NPtr<s32>)(0x800A872Cu));
    if ((mode == 0 || mode == -2) && (*(NPtr<s16>)(0x800457A4u)) == 42 && st >= 1 && st <= 29)
        return (tron_screens && (tron_v > 0 || (native_bits & 2)) && music_on && (u32)(*(NPtr<s32>)(0x80133B94u)) < 4u) ? 2 : 0;
    if (native_bits) music_off(); else music_on = 0;
    if (mode == -2 || mode == -6) return tron_live ? 1 : 0;
    return 0;
}

