static int tron_mode() { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_810F5594)(); }   // (the original calls it: the stand-in)

static NVar<int> vid_front(0); /* (private: its N64 place, bound by nm_bind) */

static u32 vid_buf_at(int k) { return k ? 0x806EA000u : 0x806E8100u; }

void tron_main(void) {
    if (tron_mode() != 2) return;
    if ((native_bits & 2) && music_on && !tron_story_on()) {
        if (!vid_ready) {
            for (u32 i = 0; (NM_TICK(), ( i < 256u)); i++) (*(NPtr<u16>)(0x806E8100u + 16u + 2u * i)) = 0x0001u;
            for (u32 i = 0; (NM_TICK(), ( i < 4096u)); i += 4u) (*(NPtr<u32>)(0x806E8100u + 16u + 512u + i)) = 0;
            vid_front = 0; vid_ready = 1;
        }
        return;
    }
    if (vid_left > 0) { vid_left--; return; }
    NVar<int> t(nm_frame_base + 0x1C); t = 0;
    u32 back = vid_buf_at(vid_front ^ 1);
    int r = media_tron_frame(tron_v, vid_k + 1, back, 1, &t);
    if (r != 1) { vid_k = -1; r = media_tron_frame(tron_v, 0, back, 1, &t); if (r != 1) return; }
    vid_k++;
    vid_left = t > 0 ? t : 4;
    vid_front ^= 1;
    vid_ready = 1;
}

