static void hc_mvp(u32 node, NPtr<float> m) {
    for (int r = 0; (NM_TICK(), ( r < 4)); r++) {
        u32 row = node + 0x5Cu + 16u * (u32)r;
        float a0 = (*(NPtr<float>)(row)); float a1 = (*(NPtr<float>)(row + 4)); float a2 = (*(NPtr<float>)(row + 8)); float a3 = (*(NPtr<float>)(row + 12));
        for (int c = 0; (NM_TICK(), ( c < 4)); c++) m[r * 4 + c] = a0 * hc_vp[c] + a1 * hc_vp[4 + c] + a2 * hc_vp[8 + c] + a3 * hc_vp[12 + c];
    }
}

