static void mtx_fixed(NPtr<float> m, u32 dst) {
    for (u32 i = 0; (NM_TICK(), ( i < 16)); i += 2) {
        float fa = m[i] * 65536.0f; float fb = m[i + 1] * 65536.0f;
        if (fa > 2.1e9f) fa = 2.1e9f; else if (fa < -2.1e9f) fa = -2.1e9f;
        if (fb > 2.1e9f) fb = 2.1e9f; else if (fb < -2.1e9f) fb = -2.1e9f;
        u32 a = (u32)(s32)fa; u32 b = (u32)(s32)fb;
        (*(NPtr<u32>)(dst + 2u * i)) = (a & 0xFFFF0000u) | (b >> 16);
        (*(NPtr<u32>)(dst + 0x20u + 2u * i)) = (a << 16) | (b & 0xFFFFu);
    }
}

