static NArr<u32> seg_base(lift_mod_address(0, 0x33E6E8), 0x40);

static u32 dl_addr(u32 a) {
    u32 sg = (a >> 24) & 15;
    if ((a >> 24) < 0x10 && sg) a = seg_base[sg] + (a & 0x00FFFFFFu);
    a = 0x80000000u | ((a) & 0x1FFFFFFFu);
    return a;
}

static void panel_apply(int i);

static void anim_find(int i, u32 mat) {
    s32 idx = (*(NPtr<s16>)(0x80083FDEu));
    if (idx < 0 || idx > 14) return;
    static /*NM_PC_CONST*/ const u32 node[2] = { 0x800836D8u, 0x80083B78u }; static /*NM_PC_CONST*/ const u32 frames[2] = { 0x800837B8u, 0x80083C58u };
    static /*NM_PC_CONST*/ const u32 count[2] = { 0x80052738u, 0x800527CCu };
    for (u32 p = 0; (NM_TICK(), ( p < 2)); p++) {
        u32 n = (*(NPtr<u16>)(count[p] + 2u * (u32)idx));
        for (u32 k = 0; (NM_TICK(), ( k < n && k < 32)); k++) {
            u32 f = (*(NPtr<u32>)(frames[p] + 4u * k));
            if (!((u32)(f) >= 0x80000400u && (u32)(f) < 0xA0000000u)) continue;
            for (u32 q = 0; (NM_TICK(), ( q < 8)); q++) {
                u32 w0 = (*(NPtr<u32>)(f + 8u * q));
                if (w0 >> 24 == 0xDF) break;
                if (w0 >> 24 == 0xDE && dl_addr((*(NPtr<u32>)(f + 8u * q + 4))) == mat) { patch[i].pin_node = node[p]; patch[i].pin_dl = f; return; }
            }
        }
    }
}

