static u32 fist_part_field(u32 part, u32 first) {
    for (u32 o = 0; (NM_TICK(), ( o < 0x34u)); o += 4u) {
        u32 p = (*(NPtr<u32>)(part + o));
        if (((u32)(p) >= 0x80000400u && (u32)(p) < 0xA0000000u) && !(p & 3u) && (*(NPtr<u32>)(p)) == first) return p;
    }
    return 0;
}

void arena_raw_anim(void) {
    static NArr<s8> was(lift_mod_address(0, 0x12EA10), 0x2);
    if (arena_current() != 0 || arena_set_mesh != (u32)xraw_set_mesh || (s32)arena_set_built <= 16) { was[0] = was[1] = -1; return; }
    u32 rate = (*(NPtr<u8>)(0x80052828u)); u32 t = (*(NPtr<u32>)(0x80057404u)) / 2u;
    if (!rate) rate = 4;
    static /*NM_PC_CONST*/ const u32 lists[2] = { 0x800526FCu, 0x80052790u }; static /*NM_PC_CONST*/ const u32 counts[2] = { 0x80052738u, 0x800527CCu };
    static /*NM_PC_CONST*/ const u16 base[2] = { 0xE44, 0xE4C }; static /*NM_PC_CONST*/ const u16 idx[2] = { 15, 16 };
    for (u32 s = 0; (NM_TICK(), ( s < 2)); s++) {
        u32 n = (*(NPtr<u16>)(counts[s])); u32 l = (*(NPtr<u32>)(lists[s]));
        if (!n || n > 32 || !((u32)(l) >= 0x80000400u && (u32)(l) < 0xA0000000u)) continue;
        l = (*(NPtr<u32>)(l));
        if (!((u32)(l) >= 0x80000400u && (u32)(l) < 0xA0000000u)) continue;
        u32 id = (*(NPtr<u16>)(l + 2u * (nm_rem((nm_div(t, rate)), n))));
        if (id < base[s] || id >= (u32)base[s] + 8u) { id = (*(NPtr<u32>)(l + 4u * (nm_rem((nm_div(t, rate)), n)))); }
        if (id < base[s] || id >= (u32)base[s] + 8u) continue;
        s32 k = (s32)(id - base[s]) / 2 + (s ? 4 : 0);
        if (was[s] == (s8)k) continue;
        u32 part = (u32)arena_set_parts + 0x34u * idx[s];
        u32 tex = fist_part_field(part, 0x1F3F0010u); u32 pal = fist_part_field(part, 0xFFFF0843u);
        if (!tex || !pal) continue;
        for (u32 b = 0; (NM_TICK(), ( b < 1032u)); b++) (*(NPtr<u8>)(tex + b)) = xraw_fist_tex[k][b];
        for (u32 b = 0; (NM_TICK(), ( b < 32u)); b++) (*(NPtr<u8>)(pal + b)) = xraw_fist_pal[k][b];
        was[s] = (s8)k;
    }
}

