static int folder_arena_count(void) {
    if (folder_arenas_n < 0) {
        int n = plat_arena_folder_count();
        if (n > (256 - 10 - 13)) n = (256 - 10 - 13);
        for (int i = 0; (NM_TICK(), ( i < n)); i++) {
            plat_arena_folder_get(i, (u32)&folder_arenas[i]);
            if (folder_arenas[i].based_on < 10 || folder_arenas[i].based_on >= 10 + 13) folder_arenas[i].based_on = 10;
        }
        folder_arenas_n = n;
    }
    return folder_arenas_n < (256 - 10 - 13) ? folder_arenas_n : (256 - 10 - 13);
}

static int arena_plays_as(int a) {
    const int i = (int)((u32)a - (10u + 13));
    return i >= 0 && i < folder_arena_count() ? folder_arenas[i].based_on : a;
}

