static int plat_arena_folder_count() { return lift_call<int>(nm_ctx, ::nm_native_call_modfn_8111FC80)(); }   // (the original calls it: the stand-in)
static void plat_arena_folder_get(int p0, u32 p1) { lift_call<void>(nm_ctx, ::nm_native_call_modfn_8111FC9C)(p0, p1); }   // (the original calls it: the stand-in)

extern u32 plat_arena_folder_file(int i, u32 id, u32 size_at);

static NArr<FolderArena> folder_arenas(lift_mod_address(0, 0x33F848), 0x20C4);

static NVar<int> folder_arenas_n(0); /* (private: its N64 place, bound by nm_bind) */

static int folder_arena_count(void) {
    if (folder_arenas_n < 0) {
        int n = plat_arena_folder_count();
        if (n > (256 - 10 - 13)) n = (256 - 10 - 13);
        for (int i = 0; (NM_TICK(), ( i < n)); i++) {
            plat_arena_folder_get(i, (u32)&folder_arenas[i]);
            if (folder_arenas[i].based_on < 10 || folder_arenas[i].based_on >= 10 + 13) folder_arenas[i].based_on = 10;
        }
        folder_arenas_n = n;
    }
    return folder_arenas_n < (256 - 10 - 13) ? folder_arenas_n : (256 - 10 - 13);
}

static int arena_plays_as(int a) {
    const int i = (int)((u32)a - (10u + 13));
    return i >= 0 && i < folder_arena_count() ? folder_arenas[i].based_on : a;
}

int arena_current(void) { return a_in ? arena_plays_as((int)(9u + (u32)a_in)) : (int)(*(NPtr<u8>)(0x800A10F1u)); }

