void ringstage_take(int a) {
    ra = (a >= 0 && a < 23 && xrs_arenas[a].cells) ? &xrs_arenas[a] : 0;
    ringstage_on = ra != 0;
    arena_count_z = ra ? (float)800 : 1e9f;
    if (ra) {
        for (u32 i = 0; (NM_TICK(), ( i < 84u)); i++) arrive_spots[i] = xrs_spots[i];
        arrive_spots[0] = ra->ax; arrive_spots[1] = ra->az; arrive_spots[2] = 2048;
    }
    arena_arrive = ra ? (u32)arrive_spots : 0x8014638Cu;
    for (int i = 0; (NM_TICK(), ( i < 32)); i++) h_now[i] = 0.0f;
}

