static NArr<float> h_now(lift_mod_address(0, 0x367640), 0x80);

static inline float abs_f(float v) { return v < 0.0f ? -v : v; }

static NVar<NPtr < XrsArena >> ra(0); /* (private: its N64 place, bound by nm_bind) */
static float ground(float p0, float p1) {   // (the original calls it with the fast convention, f0, f2: the stand-in)
    nm_ctx->f0.fl = p0; nm_ctx->f2.fl = p1; ::nm_native_call_modfn_810FDEA0(lift_rdram, nm_ctx); return nm_ctx->f0.fl;
}

static int active(void) { return ringstage_on && (*(NPtr<s32>)(0x80159628u)) < 10; }

float ringstage_lift(u32 man) {
    if (!active()) return 0.0f;
    s32 s = (*(NPtr<s16>)(man + 0x9Eu));
    if (s < 0 || s >= 32) return 0.0f;
    if ((*(NPtr<s32>)(man + 0x14u)) == 163 && ra->own_y) return 0.0f;
    float x = (*(NPtr<float>)(man + 0xFCu)); float z = (*(NPtr<float>)(man + 0x104u));
    if ((*(NPtr<u16>)(man + 0x80u)) & 1u) {
        s32 o = (*(NPtr<s32>)(man + 0x8u));
        if (o >= 0 && o < 32 && o != s) {
            float oz = (*(NPtr<float>)((0x8017FEF0u + 0x358u * (u32)(o)) + 0x104u));
            if (abs_f(oz - z) < 300.0f) { z = 0.5f * (z + oz); x = 0.5f * (x + (*(NPtr<float>)((0x8017FEF0u + 0x358u * (u32)(o)) + 0xFCu))); }
        }
    }
    float want = ground(x, z); float d = want - h_now[s];
    if (d > 60.0f || d < -60.0f) h_now[s] = want;
    else if (d > 8.0f) h_now[s] += 8.0f;
    else if (d < -8.0f) h_now[s] -= 8.0f;
    else h_now[s] = want;
    dbg_ringstage[0]++;
    return h_now[s];
}

