int ringstage_door_open(u32 man) {
    if (!active()) return 1;
    for (int s = 0; (NM_TICK(), ( s < 6)); s++) {
        u32 m = (0x8017FEF0u + 0x358u * (u32)(s));
        if (m == man || (*(NPtr<s16>)(m + 0xA0u)) == -1) continue;
        if ((*(NPtr<float>)(m + 0x104u)) >= (float)ra->front) return 1;
    }
    dbg_ringstage[1]++;
    return 0;
}

