static NVar<u32> arena_zone_look(lift_mod_address(0, 0x341A30));

static float seg_pt(float px, float pz, float ax, float az, float bx, float bz) {
    float vx = bx - ax; float vz = bz - az; float l = vx * vx + vz * vz; float t = 0.0f;
    if (l > 0.0f) { t = ((px - ax) * vx + (pz - az) * vz) / l; t = t < 0.0f ? 0.0f : t > 1.0f ? 1.0f : t; }
    float qx = ax + t * vx - px; float qz = az + t * vz - pz;
    return qx * qx + qz * qz;
}

static int seg_meet(float ax, float az, float bx, float bz, float cx, float cz, float dx, float dz) {
    float d1 = (bx - ax) * (cz - az) - (bz - az) * (cx - ax); float d2 = (bx - ax) * (dz - az) - (bz - az) * (dx - ax);
    float d3 = (dx - cx) * (az - cz) - (dz - cz) * (ax - cx); float d4 = (dx - cx) * (bz - cz) - (dz - cz) * (bx - cx);
    return ((d1 > 0.0f) != (d2 > 0.0f)) && ((d3 > 0.0f) != (d4 > 0.0f));
}

static int walls_clear(float x0, float z0, float x1, float z1, int from_too) {
    u32 l = arena_zone_look;
    if (!l) return 1;
    for (u32 s; (NM_TICK(), ( (s = (*(NPtr<u32>)(l))) != 0u)); l += 4u) {
        u32 r = (*(NPtr<u32>)(s)); u32 last = (*(NPtr<u32>)(s + 4u));
        for (int n = 0; (NM_TICK(), ( r && n < 512)); n++) {
            float ax = (float)(*(NPtr<s16>)(r)); float az = (float)(*(NPtr<s16>)(r + 4u)); float bx = (float)(*(NPtr<s16>)(r + 6u)); float bz = (float)(*(NPtr<s16>)(r + 10u));
            if ((ax != bx || az != bz) &&
                (seg_meet(x0, z0, x1, z1, ax, az, bx, bz) || (from_too && seg_pt(x0, z0, ax, az, bx, bz) < 20.0f * 20.0f) ||
                 seg_pt(x1, z1, ax, az, bx, bz) < 20.0f * 20.0f || seg_pt(ax, az, x0, z0, x1, z1) < 20.0f * 20.0f ||
                 seg_pt(bx, bz, x0, z0, x1, z1) < 20.0f * 20.0f)) return 0;
            if (r == last) break;
            r = (*(NPtr<u32>)(r + 0x2Cu));
        }
    }
    return 1;
}
