namespace nm_8111FBEC { void nm_entry(); }
void modrep_nat_8111FBEC(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    frame.keep(0x10, ctx->r16);
    nm_ctx = ctx;
    nm_8111FBEC::nm_entry();
}
