namespace nm_8111FC2C { u32 nm_entry(u32 arg0); }
u32 modrep_nat_8111FC2C(recomp_context* ctx, u32 arg0) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    return nm_8111FC2C::nm_entry(arg0);
}
