s32 modrep_nat_8111FC80(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    return nm_8111FC80::nm_entry();
}
