namespace nm_8111FE14 { void nm_entry(s32 arg0, u32 arg1); }
void modrep_nat_8111FE14(recomp_context* ctx, s32 arg0, u32 arg1) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_8111FE14::nm_entry(arg0, arg1);
}
