void modrep_nat_8111FE4C(recomp_context* ctx, s32 arg0, s32 arg1, s32 arg2, s32 arg3, u32 arg4) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_8111FE4C::nm_entry(arg0, arg1, arg2, arg3, arg4);
}
