namespace nm_8112003C { u32 nm_entry(s32 arg0, s32 arg1, u32 arg2); }
u32 modrep_nat_8112003C(recomp_context* ctx, s32 arg0, s32 arg1, u32 arg2) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    return nm_8112003C::nm_entry(arg0, arg1, arg2);
}
