void modrep_nat_81120058(recomp_context* ctx, u32 arg0, u32 arg1) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_81120058::nm_entry(arg0, arg1);
}
