namespace nm_81120154 { u32 nm_entry(u32 arg0); }
u32 modrep_nat_81120154(recomp_context* ctx, u32 arg0) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    return nm_81120154::nm_entry(arg0);
}
