namespace nm_81120170 { void nm_entry(u32 arg0, u32 arg1, u32 arg2); }
void modrep_nat_81120170(recomp_context* ctx, u32 arg0, u32 arg1, u32 arg2) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_81120170::nm_entry(arg0, arg1, arg2);
}
