namespace nm_81120288 { void nm_entry(u32 arg0, s32 arg1, s32 arg2, u32 arg3); }
void modrep_nat_81120288(recomp_context* ctx, u32 arg0, s32 arg1, s32 arg2, u32 arg3) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_81120288::nm_entry(arg0, arg1, arg2, arg3);
}
