u32 plat_config(NPtr<char> key, u32 fallback) {
    if (key[0] == 'c' && key[1] == 'o' && key[2] == 'n') {
        u32 i = (u32)recomp_get_config_u32(NPtr<char>(lift_mod_address(0, 0x9480B)));
        return i < 6 ? 5 * (i + 1) : fallback;
    }
    return (u32)recomp_get_config_u32(key);
}


