namespace nm_81120648 { void nm_entry(); }
void modrep_nat_81120648(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_81120648::nm_entry();
}
