namespace nm_811206B8 { s32 nm_entry(); }
s32 modrep_nat_811206B8(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    return nm_811206B8::nm_entry();
}
