namespace nm_811206D4 { void nm_entry(s32 arg0, s32 arg1); }
void modrep_nat_811206D4(recomp_context* ctx, s32 arg0, s32 arg1) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_811206D4::nm_entry(arg0, arg1);
}
