namespace nm_81120744 { s32 nm_entry(s32 arg0, P<s8> arg1, s32 arg2); }
s32 modrep_nat_81120744(recomp_context* ctx, s32 arg0, P<s8> arg1, s32 arg2) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    return nm_81120744::nm_entry(arg0, arg1, arg2);
}
