namespace nm_811207B4 { s32 nm_entry(s32 arg0, u32 arg1, u32 arg2, u32 arg3); }
s32 modrep_nat_811207B4(recomp_context* ctx, s32 arg0, u32 arg1, u32 arg2, u32 arg3) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    return nm_811207B4::nm_entry(arg0, arg1, arg2, arg3);
}
