namespace nm_81120EA0 { void nm_entry(u32 arg0, u32 arg1); }
void modrep_nat_81120EA0(recomp_context* ctx, u32 arg0, u32 arg1) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_81120EA0::nm_entry(arg0, arg1);
}
