namespace nm_81120F10 { void nm_entry(s32 arg0, u32 arg1, u32 arg2); }
void modrep_nat_81120F10(recomp_context* ctx, s32 arg0, u32 arg1, u32 arg2) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x14, ctx->r31);
    nm_ctx = ctx;
    nm_81120F10::nm_entry(arg0, arg1, arg2);
}
