u32 plat_pack(int which) {
    static NArr<u32> known(lift_mod_address(0, 0x36B784), 0x250);
    if (!known[which]) known[which] = recomp_arcade_pack_load(which);
    return known[which];
}

void plat_wmport_read(u32 off, u32 dst, u32 len) {
    NPtr<u8> s = (NPtr<u8>)plat_pack(PACK_WMPORT) + off; NPtr<u8> d = (NPtr<u8>)dst;
    for (u32 i = 0; (NM_TICK(), ( i < len)); i++) d[i] = s[i];
}

